CREATE TABLE event_outbox (
                event_id     TEXT  NOT NULL PRIMARY KEY REFERENCES domain_events(id) ON DELETE CASCADE,
                tenant_id    INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                status       TEXT  NOT NULL DEFAULT 'pending',
                attempts     INTEGER      NOT NULL DEFAULT 0,
                max_attempts INTEGER      NOT NULL DEFAULT 25,
                available_at TEXT NOT NULL DEFAULT (datetime('now')),
                reserved_at  TEXT,
                relayed_at   TEXT,
                last_error   TEXT,
                created_at   TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at   TEXT NOT NULL DEFAULT (datetime('now')),
                CHECK (status IN ('pending', 'reserved', 'relayed', 'dead'))
            );
CREATE INDEX idx_event_outbox_drain ON event_outbox(status, available_at);
CREATE INDEX idx_event_outbox_tenant ON event_outbox(tenant_id);
CREATE INDEX idx_event_outbox_reclaim ON event_outbox(status, reserved_at);
CREATE TABLE jobs (
                id              INTEGER     NOT NULL PRIMARY KEY,
                tenant_id       INTEGER       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                queue           TEXT   NOT NULL DEFAULT 'default',
                name            TEXT  NOT NULL,
                payload         TEXT         NOT NULL DEFAULT '{}',
                idempotency_key TEXT,
                status          TEXT   NOT NULL DEFAULT 'pending',
                priority        INTEGER       NOT NULL DEFAULT 0,
                attempts        INTEGER       NOT NULL DEFAULT 0,
                max_attempts    INTEGER       NOT NULL DEFAULT 3,
                progress        INTEGER       NOT NULL DEFAULT 0,
                result          TEXT,
                retain_result   INTEGER       NOT NULL DEFAULT 0,
                available_at    TEXT NOT NULL DEFAULT (datetime('now')),
                reserved_at     TEXT,
                completed_at    TEXT,
                last_error      TEXT,
                created_at      TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at      TEXT NOT NULL DEFAULT (datetime('now')),
                CHECK (status IN ('pending', 'reserved', 'dead', 'completed'))
            );
CREATE INDEX idx_jobs_claim ON jobs(queue, status, priority, available_at);
CREATE INDEX idx_jobs_tenant_id ON jobs(tenant_id);
CREATE INDEX idx_jobs_reclaim ON jobs(status, reserved_at);
CREATE UNIQUE INDEX uq_jobs_idempotency
            ON jobs(tenant_id, idempotency_key) WHERE idempotency_key IS NOT NULL
        ;
