                 REFERENCES profiles(id) ON DELETE SET NULL, number TEXT, number_pattern TEXT, number_assigned_at TEXT, record_type TEXT, record_id TEXT, slot TEXT, supersedes_id BIGINT REFERENCES documents(id) ON DELETE SET NULL, revision INTEGER NOT NULL DEFAULT 1, revision_reason TEXT);
