                id          INTEGER    NOT NULL PRIMARY KEY,
                tenant_id   INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                route_id    BIGINT       NOT NULL REFERENCES document_routes(id) ON DELETE CASCADE,
                position    INTEGER      NOT NULL,
                rule_kind   TEXT NOT NULL,
                rule_config TEXT        NOT NULL DEFAULT '{}',
                label       TEXT,
                created_at  TEXT NOT NULL DEFAULT (datetime('now')), decision INTEGER NOT NULL DEFAULT 0, decision_quorum TEXT
                CHECK (decision_quorum IS NULL OR decision_quorum IN ('all', 'any', 'majority', 'first')), satisfied_by TEXT NOT NULL DEFAULT 'act'
                CHECK (satisfied_by IN ('act', 'delivery')), kind TEXT NOT NULL DEFAULT 'review'
                CHECK (kind IN ('review', 'decide', 'deliver', 'sign', 'stamp', 'finalise')), allow_send_back INTEGER NOT NULL DEFAULT 1, sign_capacity TEXT, sign_on_behalf_of TEXT, final_template_id BIGINT, inputs TEXT, exclude_named_in TEXT, left_out TEXT,
                UNIQUE (route_id, position)
            );
