                ON document_route_steps(tenant_id, route_id, position);
CREATE TABLE document_route_events (
                id               INTEGER   NOT NULL PRIMARY KEY,
                tenant_id        INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                document_id      BIGINT      REFERENCES documents(id) ON DELETE CASCADE,
                route_id         BIGINT      NOT NULL REFERENCES document_routes(id) ON DELETE CASCADE,
                step_id          BIGINT      REFERENCES document_route_steps(id) ON DELETE SET NULL,
                actor_profile_id INTEGER     REFERENCES profiles(id) ON DELETE SET NULL,
                action           TEXT NOT NULL,
                from_ou_id       INTEGER     REFERENCES organizational_units(id) ON DELETE SET NULL,
                to_ou_id         INTEGER     REFERENCES organizational_units(id) ON DELETE SET NULL,
                note             TEXT,
                occurred_at      TEXT NOT NULL DEFAULT (datetime('now')), verdict TEXT
                CHECK (verdict IS NULL OR verdict IN ('approved', 'rejected')), withdrawal INTEGER NOT NULL DEFAULT 0, subject_version INTEGER, content_hash TEXT, to_author INTEGER NOT NULL DEFAULT 0, resume_from TEXT
                 CHECK (resume_from IS NULL OR resume_from IN ('sender', 'start')), prev_hash TEXT, entry_hash TEXT, entry_body TEXT, on_behalf_of_profile_id INTEGER REFERENCES profiles(id) ON DELETE SET NULL,
                CHECK (action IN ('issued', 'forwarded', 'acknowledged', 'returned', 'noted', 'sent_back', 'resubmitted', 'signed', 'stamped', 'declined'))
            );
CREATE INDEX idx_document_route_events_tenant_id ON document_route_events(tenant_id);
