                 REFERENCES profiles(id) ON DELETE SET NULL, sections TEXT NOT NULL DEFAULT '[]', submit_label TEXT, reference_format TEXT, open_to_members INTEGER NOT NULL DEFAULT 0, members_opened_at TEXT, members_opened_by_profile_id INTEGER
