CREATE TABLE plan_prices (
                id           INTEGER     NOT NULL PRIMARY KEY,
                plan_id      BIGINT        NOT NULL REFERENCES plans(id) ON DELETE CASCADE,

                -- ISO 4217, upper case. Three characters exactly; a CHECK would
                -- be tempting but the list changes (currencies are added and
                -- retired) and a migration is a bad place to freeze one.
                currency     TEXT    NOT NULL,

                -- Minor units. See the class note: never a decimal, never a
                -- float, and no exponent — that belongs to the currency.
                unit_amount  BIGINT        NOT NULL,

                -- 'month' | 'year' | 'once'. A one-off price is how a perpetual
                -- licence or a setup fee is expressed, and leaving it out would
                -- push those into a second table for no gain.
                billing_period TEXT NOT NULL,

                -- Does unit_amount multiply by the tenant's seat count?
                is_per_seat  INTEGER       NOT NULL DEFAULT 0,

                -- A price is switched off rather than deleted. Deleting one that
                -- a tenant is being billed against would leave a subscription
                -- pointing at nothing, and the row is also the evidence of what
                -- somebody was charged.
                is_active    INTEGER       NOT NULL DEFAULT 1,

                created_at   TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at   TEXT NOT NULL DEFAULT (datetime('now'))
            , is_per_device INTEGER NOT NULL DEFAULT 0, external_ref TEXT);
CREATE INDEX idx_plan_prices_plan_id ON plan_prices(plan_id);
CREATE TABLE promotions (
                id             INTEGER     NOT NULL PRIMARY KEY,

                -- What an operator calls it. Always present, including for a
                -- coded promotion: a report listing 'SUMMER24' tells nobody what
                -- it was for six months later.
                name           TEXT  NOT NULL,

                -- NULL = automatic (an early bird, an offer). Present = the
                -- customer must type it. Stored upper case so 'summer24' and
                -- 'SUMMER24' cannot become two promotions.
                code           TEXT,

                -- Exactly one of these is set; the CHECK below enforces it.
                percent_off    INTEGER,
                amount_off     BIGINT,
                -- Required with amount_off, forbidden without: a fixed discount
                -- is an amount of a particular currency or it is nothing.
                currency       TEXT,

                -- Open-ended at either end. A promotion with neither is simply
                -- always valid, which is a legitimate thing to want.
                starts_at      TEXT,
                ends_at        TEXT,

                -- NULL = unlimited. The early bird's defining feature is
                -- usually this rather than the window.
                max_redemptions            INTEGER,
                -- How many times ONE tenant may take it. Defaults to 1, because
                -- the alternative default lets a single tenant consume a whole
                -- early-bird allocation.
                max_redemptions_per_tenant INTEGER  NOT NULL DEFAULT 1,

                -- Switched off rather than deleted: a redeemed promotion is
                -- evidence of why a tenant is paying what they are paying.
                is_active      INTEGER       NOT NULL DEFAULT 1,

                created_at     TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at     TEXT NOT NULL DEFAULT (datetime('now')),

                -- One kind or the other, never both and never neither. Without
                -- this a row could carry 20% AND 50 SAR and every caller would
                -- have to invent a precedence rule of its own.
                CONSTRAINT promotions_one_kind CHECK (
                    (percent_off IS NOT NULL AND amount_off IS NULL AND currency IS NULL)
                    OR
                    (percent_off IS NULL AND amount_off IS NOT NULL AND currency IS NOT NULL)
                ),
                CONSTRAINT promotions_percent_range CHECK (
                    percent_off IS NULL OR (percent_off > 0 AND percent_off <= 100)
                ),
                CONSTRAINT promotions_amount_positive CHECK (
                    amount_off IS NULL OR amount_off > 0
                )
            );
CREATE UNIQUE INDEX uq_promotions_active_code
                 ON promotions(code)
              WHERE code IS NOT NULL AND is_active;
CREATE TABLE promotion_plans (
                promotion_id BIGINT NOT NULL REFERENCES promotions(id) ON DELETE CASCADE,
                plan_id      BIGINT NOT NULL REFERENCES plans(id) ON DELETE CASCADE,
                PRIMARY KEY (promotion_id, plan_id)
            );
CREATE TABLE promotion_redemptions (
                id           INTEGER  NOT NULL PRIMARY KEY,
                promotion_id BIGINT     NOT NULL REFERENCES promotions(id) ON DELETE CASCADE,
                tenant_id    INTEGER    NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                redeemed_at  TEXT NOT NULL DEFAULT (datetime('now')),
                -- What it was worth at the moment it was taken, in minor units.
                -- Recomputing it later would give a different answer once the
                -- price moved, and the question people ask is what they were
                -- actually charged.
                amount_discounted BIGINT,
                currency          TEXT
            );
CREATE INDEX idx_promotion_redemptions_promotion ON promotion_redemptions(promotion_id);
CREATE INDEX idx_promotion_redemptions_tenant ON promotion_redemptions(tenant_id);
CREATE TABLE invoices (
                id             INTEGER     NOT NULL PRIMARY KEY,

                -- RESTRICT, not CASCADE. See the class docblock: this is a tax
                -- record with a statutory retention period, and the tenant
                -- delete endpoint is expected to check before it asks.
                tenant_id      INTEGER       NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,

                -- OPTIONAL SUBUSER SCOPE. Almost every invoice is addressed to
                -- the tenant, and this is NULL. It exists because billing an
                -- individual member is a stated requirement and retrofitting a
                -- scope column onto a table of issued invoices means deciding
                -- what the existing rows meant — a question with no good
                -- answer once real invoices are in it.
                --
                -- SET NULL rather than cascade: the invoice is the tenant's
                -- either way, and a departing employee must not take a tax
                -- record with them.
                profile_id     INTEGER       REFERENCES profiles(id) ON DELETE SET NULL,

                -- NULL while draft; allocated at issue. The CHECK below pairs
                -- the two so neither can drift from the other.
                number         TEXT,

                -- The name of the sequence the number came from. (series,
                -- number) is unique, which is the whole claim numbering makes.
                series         TEXT   NOT NULL DEFAULT 'default',

                -- draft -> open -> paid, with void and uncollectible as the
                -- two ways an open invoice ends without being paid. 'open'
                -- rather than 'issued' because it is the word the rest of the
                -- billing world uses for 'sent, unpaid, still owed', and a
                -- status vocabulary that differs from every integration we will
                -- ever write is a translation layer nobody maintains.
                --
                -- Voiding keeps the row and its number: a cancelled invoice
                -- that vanishes leaves a hole that looks like a lost one.
                status         TEXT   NOT NULL DEFAULT 'draft',

                currency       TEXT    NOT NULL,

                -- Minor units, always. NET of tax even when prices are quoted
                -- tax-inclusive, so the invariant CHECK holds either way.
                subtotal_minor BIGINT        NOT NULL DEFAULT 0,
                discount_minor BIGINT        NOT NULL DEFAULT 0,
                tax_minor      BIGINT        NOT NULL DEFAULT 0,
                total_minor    BIGINT        NOT NULL DEFAULT 0,

                -- Snapshots of the tax treatment as it stood at issue. A rate
                -- change next year must not restate this invoice.
                tax_rate_bp    INTEGER       NOT NULL DEFAULT 0,
                tax_label      TEXT   NOT NULL DEFAULT '',
                tax_inclusive  INTEGER       NOT NULL DEFAULT 0,

                -- Both parties as they were. The seller comes from settings,
                -- the buyer from the tenant; neither is joined at render time.
                seller_name    TEXT  NOT NULL DEFAULT '',
                seller_address TEXT,
                seller_tax_id  TEXT,
                buyer_name     TEXT  NOT NULL DEFAULT '',
                buyer_address  TEXT,
                buyer_tax_id   TEXT,

                -- Trace only. Nothing renders from these, and SET NULL says
                -- losing the trace must not lose the invoice.
                plan_id        BIGINT        REFERENCES plans(id) ON DELETE SET NULL,
                promotion_id   BIGINT        REFERENCES promotions(id) ON DELETE SET NULL,

                -- What period this invoice covers, which is not when it was
                -- issued and not when it is due.
                period_start   DATE,
                period_end     DATE,

                issued_at      TEXT,
                due_at         TEXT,
                paid_at        TEXT,
                voided_at      TEXT,
                void_reason    TEXT,

                -- Free text that prints on the document (a PO number, payment
                -- instructions, a note about the period).
                notes          TEXT,

                created_at     TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at     TEXT NOT NULL DEFAULT (datetime('now')),

                CONSTRAINT invoices_status CHECK (
                    status IN ('draft', 'open', 'paid', 'void', 'uncollectible')
                ),

                -- A draft has no number and anything past draft has one. The
                -- pair is the mechanism that keeps abandoned drafts from
                -- punching holes in the sequence, so it is enforced rather than
                -- left as a convention for every write path to remember.
                CONSTRAINT invoices_number_matches_status CHECK (
                    (status = 'draft' AND number IS NULL)
                    OR
                    (status <> 'draft' AND number IS NOT NULL)
                ),

                -- An invoice that does not add up cannot be stored. The bug
                -- this catches produces a plausible number, and a plausible
                -- wrong number is found by the customer rather than by us.
                CONSTRAINT invoices_totals_add_up CHECK (
                    total_minor = subtotal_minor - discount_minor + tax_minor
                ),

                CONSTRAINT invoices_amounts_non_negative CHECK (
                    subtotal_minor >= 0 AND discount_minor >= 0 AND tax_minor >= 0
                ),

                -- A discount larger than what is being discounted would make
                -- the total negative, which is a credit note and not this.
                CONSTRAINT invoices_discount_within_subtotal CHECK (
                    discount_minor <= subtotal_minor
                ),

                CONSTRAINT invoices_tax_rate_range CHECK (
                    tax_rate_bp >= 0 AND tax_rate_bp <= 10000
                )
            );
CREATE UNIQUE INDEX uq_invoices_series_number
                 ON invoices(series, number)
              WHERE number IS NOT NULL;
CREATE INDEX idx_invoices_tenant_status ON invoices(tenant_id, status);
CREATE INDEX idx_invoices_tenant_issued ON invoices(tenant_id, issued_at);
CREATE TABLE invoice_lines (
                id                INTEGER    NOT NULL PRIMARY KEY,
                invoice_id        BIGINT       NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,

                -- Denormalised from the parent so the tenant-predicate guard
                -- polices a line read directly instead of trusting a join —
                -- the same trade `document_artifacts` and `entity_tags` make.
                tenant_id         INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,

                -- The order the operator arranged them in. Rendering by `id`
                -- would be right by accident until the first edited draft.
                position          INTEGER      NOT NULL DEFAULT 0,

                description       TEXT NOT NULL,
                quantity          INTEGER      NOT NULL DEFAULT 1,
                unit_amount_minor BIGINT       NOT NULL DEFAULT 0,

                subtotal_minor    BIGINT       NOT NULL DEFAULT 0,
                discount_minor    BIGINT       NOT NULL DEFAULT 0,

                -- Per line, because mixed-rate invoices are ordinary: a
                -- zero-rated export line beside a standard-rated support line.
                tax_rate_bp       INTEGER      NOT NULL DEFAULT 0,
                tax_minor         BIGINT       NOT NULL DEFAULT 0,
                total_minor       BIGINT       NOT NULL DEFAULT 0,

                created_at        TEXT NOT NULL DEFAULT (datetime('now')),

                CONSTRAINT invoice_lines_quantity_positive CHECK (quantity > 0),
                CONSTRAINT invoice_lines_totals_add_up CHECK (
                    total_minor = subtotal_minor - discount_minor + tax_minor
                ),
                CONSTRAINT invoice_lines_discount_within_subtotal CHECK (
                    discount_minor <= subtotal_minor
                ),
                CONSTRAINT invoice_lines_tax_rate_range CHECK (
                    tax_rate_bp >= 0 AND tax_rate_bp <= 10000
                )
            );
CREATE UNIQUE INDEX uq_invoice_lines_position
                 ON invoice_lines(invoice_id, position);
CREATE INDEX idx_invoice_lines_tenant ON invoice_lines(tenant_id);
CREATE TABLE payment_methods (
                id             INTEGER     NOT NULL PRIMARY KEY,
                tenant_id      INTEGER       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,

                -- Optional subuser scope, mirroring `invoices`: a member paying
                -- for their own seat has their own instrument on file.
                profile_id     INTEGER       REFERENCES profiles(id) ON DELETE CASCADE,

                -- Which rail this belongs to ('cliq', 'mock', and whichever
                -- card provider is chosen). A string, not a CHECK — see the
                -- class docblock.
                provider       TEXT   NOT NULL,

                -- THE PROVIDER'S identifier, opaque to us. Not parsed, not
                -- validated beyond being present, never assumed to have a
                -- shape.
                external_id    TEXT  NOT NULL,

                -- Enough to show a person which method they picked — a masked
                -- tail, a bank name, an alias. TEXT because what is available
                -- differs per provider, and columns for one provider's fields
                -- would be null for every other.
                display_meta   TEXT,

                -- Exactly one default per (tenant, provider) is enforced by a
                -- partial unique index below, rather than by whichever write
                -- path remembers to clear the others.
                is_default     INTEGER       NOT NULL DEFAULT 0,

                -- Detached rather than deleted: a transaction refers to the
                -- method that produced it, and the history must survive the
                -- customer removing the card.
                is_active      INTEGER       NOT NULL DEFAULT 1,

                created_at     TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at     TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE UNIQUE INDEX uq_payment_methods_provider_external
                 ON payment_methods(provider, external_id);
CREATE UNIQUE INDEX uq_payment_methods_one_default
                 ON payment_methods(tenant_id, provider)
              WHERE is_default AND is_active;
CREATE INDEX idx_payment_methods_tenant ON payment_methods(tenant_id);
CREATE TABLE payment_transactions (
                id             INTEGER     NOT NULL PRIMARY KEY,
                tenant_id      INTEGER       NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,

                -- Nullable: money can arrive before anyone decides which
                -- invoice it settles, and forcing that decision at the moment
                -- of arrival is how a payment gets applied to the wrong one.
                -- RESTRICT because deleting an invoice out from under its
                -- transaction would leave money in the ledger belonging to
                -- nothing.
                invoice_id     BIGINT        REFERENCES invoices(id) ON DELETE RESTRICT,

                -- Which instrument, when there was one. A CliQ push has none:
                -- the payer chose it in their own bank's app.
                payment_method_id BIGINT     REFERENCES payment_methods(id) ON DELETE SET NULL,

                provider       TEXT   NOT NULL,

                -- The provider's own identifier for this movement. Unique per
                -- provider among rows that have one — the schema-level
                -- idempotency described in the class docblock.
                external_reference TEXT,

                -- pending  : initiated, outcome unknown (a transfer in flight)
                -- succeeded: money moved
                -- failed   : it did not, and dunning cares about this one
                -- refunded : reversed; the reversal is its own negative row,
                --            and this marks the original
                status         TEXT   NOT NULL DEFAULT 'pending',

                -- Minor units. NEGATIVE IS A REFUND.
                amount_minor   BIGINT        NOT NULL,
                currency       TEXT    NOT NULL,

                -- Why it failed, in the provider's words, kept for the
                -- operator rather than shown to the customer.
                failure_reason TEXT,

                -- The raw payload that produced this row, for reconciling a
                -- dispute months later against what the provider actually
                -- sent. Never parsed for business logic — the normalised
                -- columns above are what anything reads.
                raw_payload    TEXT,

                -- When the money moved, which is not when we heard about it.
                -- A webhook arriving late must not date the payment to its own
                -- arrival, or a payment made inside a grace period looks like
                -- one made after it expired.
                occurred_at    TEXT NOT NULL DEFAULT (datetime('now')),

                -- Who keyed it in, for a manual reconciliation. SET NULL
                -- because a departed employee's record must survive them.
                recorded_by_profile_id INTEGER REFERENCES profiles(id) ON DELETE SET NULL,

                note           TEXT,
                created_at     TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at     TEXT NOT NULL DEFAULT (datetime('now')),

                CONSTRAINT payment_transactions_status CHECK (
                    status IN ('pending', 'succeeded', 'failed', 'refunded')
                ),

                -- Zero is a record of nothing.
                CONSTRAINT payment_transactions_amount_non_zero CHECK (amount_minor <> 0)
            );
CREATE UNIQUE INDEX uq_payment_transactions_provider_reference
                 ON payment_transactions(provider, external_reference)
              WHERE external_reference IS NOT NULL;
CREATE INDEX idx_payment_transactions_invoice
                 ON payment_transactions(invoice_id);
CREATE INDEX idx_payment_transactions_tenant_occurred
                 ON payment_transactions(tenant_id, occurred_at);
CREATE INDEX idx_payment_transactions_status
                 ON payment_transactions(status, occurred_at);
CREATE UNIQUE INDEX uq_invoices_subscription_period
                 ON invoices(tenant_id, plan_id, period_start)
              WHERE plan_id IS NOT NULL AND period_start IS NOT NULL;
CREATE TABLE licensed_devices (
                id INTEGER PRIMARY KEY,

                -- ON DELETE RESTRICT, matching invoices. A licensed device is a
                -- commercial record: something was sold, and deleting the tenant
                -- must not silently take the evidence with it.
                tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,

                -- The manufacturer's identifier, as printed. Stored as given
                -- rather than normalised, because a INTEGER is evidence and the
                -- customer will read it off the unit when they query a bill.
                serial_number TEXT NOT NULL,

                -- What a human calls it. Optional: a warehouse import has
                -- serials and nothing else.
                label TEXT,

                status TEXT NOT NULL DEFAULT 'provisioned',

                -- The three facts the billing policy chooses between. See the
                -- class docblock: none of them is 'the' answer.
                provisioned_at TEXT NOT NULL DEFAULT (datetime('now')),
                activated_at TEXT,
                last_seen_at TEXT,
                retired_at TEXT,

                -- Room for a deployment's own fields without a migration each
                -- time. Deliberately not a place for anything this schema needs
                -- to query or enforce.
                metadata TEXT,

                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at TEXT NOT NULL DEFAULT (datetime('now')),

                CONSTRAINT chk_licensed_device_status
                    CHECK (status IN ('provisioned', 'active', 'suspended', 'retired')),

                -- An ACTIVE device must know when it was activated, because the
                -- activation date is what an activation-based invoice is
                -- computed from. Letting the two disagree would make a bill
                -- unexplainable.
                CONSTRAINT chk_licensed_device_active_has_date
                    CHECK (status <> 'active' OR activated_at IS NOT NULL)
            );
CREATE UNIQUE INDEX uq_licensed_devices_tenant_serial
                ON licensed_devices (tenant_id, serial_number)
        ;
CREATE INDEX idx_licensed_devices_tenant_status
                ON licensed_devices (tenant_id, status)
        ;
CREATE TABLE device_activation_codes (
                id INTEGER PRIMARY KEY,

                tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,

                -- GLOBALLY UNIQUE, not unique-per-tenant. A student redeeming a
                -- code off a sticker does not know which tenant they belong to
                -- and must not have to; the code itself has to be sufficient to
                -- identify the tenant, the device and the grant. Scoping it per
                -- tenant would force the redemption endpoint to accept a tenant
                -- hint from an untrusted caller, which is precisely how one
                -- customer's code gets redeemed against another's account.
                code TEXT NOT NULL,

                -- A code may be minted FOR a specific unit, or left open and
                -- bound to whichever device redeems it. Both are real: serials
                -- printed at manufacture versus a batch handed to a school.
                licensed_device_id BIGINT REFERENCES licensed_devices(id) ON DELETE CASCADE,

                -- NOT a INTEGER. 'Single use' is the default and the common
                -- case, but a classroom set of thirty, or an unlimited campus
                -- code that expires at term end, are ordinary requirements — and
                -- a INTEGER cannot express either. Business logic and marketing
                -- intent are not guessable from here, so this is a number with a
                -- sensible default rather than a decision baked into the type.
                max_redemptions INTEGER NOT NULL DEFAULT 1,
                redemption_count INTEGER NOT NULL DEFAULT 0,

                -- NULL means no expiry. Both are wanted.
                expires_at TEXT,

                -- Revocation is separate from expiry and from exhaustion: a code
                -- printed on a batch of stickers that went missing must be
                -- killable while still unexpired and unredeemed.
                revoked_at TEXT,

                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at TEXT NOT NULL DEFAULT (datetime('now')),

                CONSTRAINT chk_activation_max_redemptions
                    CHECK (max_redemptions >= 1),

                -- THE INVARIANT THAT MATTERS, enforced by the database rather
                -- than by whichever code path happens to be redeeming. A race
                -- between two students typing the last code of a batch is a
                -- normal Tuesday, and application-level checking loses it.
                CONSTRAINT chk_activation_not_over_redeemed
                    CHECK (redemption_count <= max_redemptions)
            );
CREATE UNIQUE INDEX uq_device_activation_codes_code
                ON device_activation_codes (code)
        ;
CREATE INDEX idx_device_activation_codes_tenant
                ON device_activation_codes (tenant_id)
        ;
CREATE TABLE device_activation_redemptions (
                id INTEGER PRIMARY KEY,

                tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,
                -- ON ONE LINE EACH, deliberately. The undeclared-reference guard
                -- reads a column's definition per line, so a REFERENCES clause
                -- wrapped onto the next one is invisible to it and the column is
                -- reported as an undeclared edge. It errs safely — a false alarm
                -- rather than a missed violation — but the fix is to write these
                -- the way every other migration here does.
                activation_code_id BIGINT NOT NULL REFERENCES device_activation_codes(id) ON DELETE RESTRICT,
                licensed_device_id BIGINT NOT NULL REFERENCES licensed_devices(id) ON DELETE RESTRICT,

                -- Who redeemed it, when known. NULL is expected and legitimate:
                -- the whole point is that an end user or student may redeem
                -- without an account, and recording a null is more honest than
                -- inventing an actor.
                redeemed_by_user_id BIGINT,

                -- Kept for abuse investigation, not for identification.
                redeemed_from_ip TEXT,

                redeemed_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_device_redemptions_code
                ON device_activation_redemptions (activation_code_id)
        ;
CREATE INDEX idx_device_redemptions_tenant
                ON device_activation_redemptions (tenant_id, redeemed_at)
        ;
CREATE UNIQUE INDEX uq_plan_prices_active
                ON plan_prices(plan_id, currency, billing_period, is_per_seat, is_per_device)
             WHERE is_active
        ;
CREATE INDEX idx_plans_addon_active
                ON plans(is_addon, is_active)
        ;
CREATE INDEX idx_plans_provider
                ON plans(provider)
        ;
CREATE TABLE affiliates (
                id INTEGER PRIMARY KEY,

                -- What goes in the link. Case-insensitively unique, because a
                -- referrer will write it on a slide and somebody will type it
                -- back in the wrong case.
                code TEXT NOT NULL,

                name TEXT NOT NULL,

                -- The person, when they have an account here. Nullable: an
                -- affiliate is often an outside partner who never signs in, and
                -- requiring an account would mean creating one nobody uses.
                -- ON DELETE SET NULL — deleting a profile must not destroy the
                -- record of money owed to them.
                profile_id BIGINT REFERENCES profiles(id) ON DELETE SET NULL,

                -- Where to reach them about a payout. Kept even when profile_id
                -- is set: the person who signs in is not always the person who
                -- gets paid.
                email TEXT,

                -- BASIS POINTS, not a percent. 2000 = 20%. Integer arithmetic
                -- all the way, mirroring invoices.tax_rate_bp, because a rate
                -- stored as a float is a rounding argument with somebody about
                -- their own money.
                commission_bp INTEGER NOT NULL,

                -- How long after their first payment a referred customer keeps
                -- earning. Per affiliate, because it is a term in a deal.
                window_months INTEGER NOT NULL DEFAULT 12,

                -- The discount the code ALSO grants, when it grants one. Most
                -- affiliate codes do; some are commission-only. Nullable rather
                -- than two kinds of affiliate.
                -- ON DELETE SET NULL: retiring a promotion must not delete the
                -- affiliate or their earnings.
                promotion_id BIGINT REFERENCES promotions(id) ON DELETE SET NULL,

                is_active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE UNIQUE INDEX idx_affiliates_code ON affiliates (LOWER(code));
CREATE INDEX idx_affiliates_active ON affiliates (is_active);
CREATE TABLE affiliate_referrals (
                id INTEGER PRIMARY KEY,

                affiliate_id BIGINT NOT NULL REFERENCES affiliates(id) ON DELETE RESTRICT,

                -- ON DELETE RESTRICT, matching invoices: a referral is a
                -- commercial record, and deleting the workspace must not
                -- silently take the evidence of what somebody earned with it.
                tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,

                referred_at TEXT NOT NULL DEFAULT (datetime('now')),

                -- THE WINDOW STARTS AT THE FIRST PAYMENT, not at signup. A
                -- referrer whose customer takes two months to convert should get
                -- twelve months of revenue, not ten. Null until they pay, which
                -- is also how 'referred but never converted' is expressed.
                first_paid_at TEXT,

                -- Computed when first_paid_at is set, then never moved. Stored
                -- rather than derived so a later change to the affiliate's
                -- window_months cannot silently re-open or close a window that
                -- both parties already agreed.
                window_ends_at TEXT,

                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at TEXT NOT NULL DEFAULT (datetime('now')),

                -- ONE REFERRER PER WORKSPACE, FOR GOOD. Enforced by the schema
                -- rather than by whoever writes the attribution code: two
                -- affiliates claiming the same customer is not a conflict
                -- anybody notices until both are being paid for it.
                --
                -- A table constraint, so it sits after every column: placed
                -- mid-list it is a syntax error on both engines, which is how
                -- this was found.
                CONSTRAINT uq_affiliate_referrals_tenant UNIQUE (tenant_id)
            );
CREATE INDEX idx_affiliate_referrals_affiliate ON affiliate_referrals (affiliate_id);
CREATE INDEX idx_affiliate_referrals_tenant ON affiliate_referrals (tenant_id);
CREATE TABLE affiliate_payouts (
                id INTEGER PRIMARY KEY,

                affiliate_id BIGINT NOT NULL REFERENCES affiliates(id) ON DELETE RESTRICT,

                total_minor BIGINT NOT NULL,
                currency TEXT NOT NULL,

                -- draft while it is being assembled, paid once the money has
                -- actually moved. There is no 'sent' between them, because
                -- nothing here sends money — a human does, and then says so.
                status TEXT NOT NULL DEFAULT 'draft',

                -- The bank or transfer reference. Free text on purpose: this is
                -- whatever the person who made the payment can quote back when
                -- an affiliate asks where their money went.
                reference TEXT,

                paid_at TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at TEXT NOT NULL DEFAULT (datetime('now'))
            , withholding_bp INTEGER NOT NULL DEFAULT 0, withholding_minor BIGINT NOT NULL DEFAULT 0, net_minor BIGINT NOT NULL DEFAULT 0, assembled_by_profile_id INTEGER
                 REFERENCES profiles(id) ON DELETE SET NULL, paid_by_profile_id INTEGER
                 REFERENCES profiles(id) ON DELETE SET NULL);
CREATE INDEX idx_affiliate_payouts_affiliate ON affiliate_payouts (affiliate_id, status);
CREATE TABLE affiliate_commissions (
                id INTEGER PRIMARY KEY,

                referral_id BIGINT NOT NULL REFERENCES affiliate_referrals(id) ON DELETE RESTRICT,
                affiliate_id BIGINT NOT NULL REFERENCES affiliates(id) ON DELETE RESTRICT,

                -- WHICH PAYMENT THIS CAME FROM. 'invoice' for one we raised,
                -- 'external' for one the billing service did. Together with
                -- source_ref this is what makes the accrual sweep idempotent:
                -- re-running it cannot pay for the same payment twice.
                -- WIDE ENOUGH FOR THE REVERSAL MARKER. At TEXT the value
                -- 'external:reversal' (17 characters) was rejected by PostgreSQL
                -- and silently accepted by SQLite, so every clawback failed in
                -- production and passed in the local suite. Caught by the
                -- dual-engine gate, not by reading.
                source TEXT NOT NULL,
                source_ref TEXT NOT NULL,

                -- What the rate was applied to: the invoice AFTER discounts and
                -- EXCLUDING tax. Tax is not income and is not ours to share.
                base_minor BIGINT NOT NULL,

                -- COPIED, NEVER JOINED FOR. The affiliate's rate today is not
                -- the rate this commission was earned at, and an earnings report
                -- that silently rewrites itself when somebody renegotiates is
                -- not a report.
                rate_bp INTEGER NOT NULL,

                amount_minor BIGINT NOT NULL,
                currency TEXT NOT NULL,

                -- accrued -> approved -> paid, with reversed as the terminal
                -- state for a clawback. A reversal is a NEW row with a negative
                -- amount rather than an edit, so a balance stays a SUM and the
                -- history of what happened survives.
                status TEXT NOT NULL DEFAULT 'accrued',

                -- When the customer paid, not when we noticed. A sweep that runs
                -- late must not move an earning into the wrong month.
                occurred_at TEXT NOT NULL,

                -- ON DELETE SET NULL: discarding a draft payout returns its
                -- commissions to the unpaid pool rather than orphaning them.
                -- Without the key, deleting a payout leaves rows pointing at an
                -- id that no longer resolves and nothing refuses it — which the
                -- reference guard caught before this shipped.
                payout_id BIGINT REFERENCES affiliate_payouts(id) ON DELETE SET NULL,

                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at TEXT NOT NULL DEFAULT (datetime('now')),

                -- ONE COMMISSION PER PAYMENT. The accrual sweep re-reads a
                -- customer's whole payment history every run, so this is what
                -- stops the second run paying for the first run's work. A
                -- reversal is distinguished by source, not by a second row with
                -- the same key.
                CONSTRAINT uq_affiliate_commissions_source UNIQUE (referral_id, source, source_ref)
            );
CREATE INDEX idx_affiliate_commissions_affiliate ON affiliate_commissions (affiliate_id, status);
CREATE INDEX idx_affiliate_commissions_payout ON affiliate_commissions (payout_id);
CREATE INDEX idx_tenant_plan_billed_externally
                ON tenant_plan(tenant_id) WHERE billed_externally
        ;
CREATE TABLE document_sources (
                id                    INTEGER     NOT NULL PRIMARY KEY,
                tenant_id             INTEGER       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                kind                  TEXT   NOT NULL,
                title                 TEXT  NOT NULL DEFAULT '',
                lang                  TEXT    NOT NULL DEFAULT 'en',
                default_view          TEXT   NOT NULL DEFAULT 'continuous',
                full_width            INTEGER       NOT NULL DEFAULT 0,
                page                  TEXT,
                record_type           TEXT,
                blocks                TEXT         NOT NULL,
                draft_version         INTEGER       NOT NULL DEFAULT 1,
                published_version     INTEGER,
                scope                 TEXT   NOT NULL DEFAULT 'personal',
                required_permission   TEXT,
                created_by            BIGINT,
                owner_ou_id           BIGINT,
                updated_by            BIGINT,
                created_at            TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at            TEXT NOT NULL DEFAULT (datetime('now'))
            , own_fields TEXT, starter_key TEXT, legacy_template_id BIGINT, theme TEXT, numbering TEXT, public_name TEXT);
CREATE INDEX idx_document_sources_tenant_id ON document_sources(tenant_id);
CREATE INDEX idx_document_sources_tenant_kind ON document_sources(tenant_id, kind);
CREATE INDEX idx_document_sources_tenant_updated ON document_sources(tenant_id, updated_at);
CREATE TABLE document_source_versions (
                id                       INTEGER     NOT NULL PRIMARY KEY,
