                source_id                BIGINT        NOT NULL REFERENCES document_sources(id) ON DELETE CASCADE,
                version                  INTEGER       NOT NULL,
                title                    TEXT  NOT NULL,
                page                     TEXT,
                blocks                   TEXT         NOT NULL,
                published_by_profile_id  INTEGER       REFERENCES profiles(id) ON DELETE SET NULL,
                published_at             TEXT NOT NULL DEFAULT (datetime('now')), own_fields TEXT, theme TEXT, theme_resolved TEXT,
                UNIQUE (source_id, version)
            );
CREATE INDEX idx_document_source_versions_tenant_source ON document_source_versions(tenant_id, source_id);
CREATE INDEX idx_document_sources_tenant_starter ON document_sources(tenant_id, starter_key);
