                tenant_id          INTEGER       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                plugin_key         TEXT   NOT NULL,
                version            TEXT   NOT NULL,
                manifest           TEXT         NOT NULL,
                hash               CHAR(64)      NOT NULL,
                notes              TEXT,
                published_by       BIGINT,
                acting_for         BIGINT,
