            );
CREATE INDEX idx_document_themes_tenant_id ON document_themes(tenant_id);
CREATE TABLE plugin_automation_runs (
                id                 INTEGER     NOT NULL PRIMARY KEY,
                tenant_id          INTEGER       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                plugin_key         TEXT   NOT NULL,
                automation_key     TEXT   NOT NULL,
                event              TEXT  NOT NULL,
                record_type        TEXT   NOT NULL,
                -- @reference-lint-ignore: the record the run was about, kept in its trace after the record is deleted
                record_id          BIGINT        NOT NULL,
                depth              SMALLINT      NOT NULL,
                root_run_id        BIGINT        REFERENCES plugin_automation_runs(id) ON DELETE CASCADE,
                automation_hash    TEXT   NOT NULL,
                -- @reference-lint-ignore: who caused the run, kept in its trace like the audit trail keeps an actor; it outlives the profile
                actor_profile_id   BIGINT,
                status             TEXT   NOT NULL,
                reason             TEXT,
                trace              TEXT         NOT NULL,
                created_at         TEXT NOT NULL DEFAULT (datetime('now')),
                finished_at        TEXT
            );
CREATE INDEX idx_plugin_automation_runs_plugin ON plugin_automation_runs(tenant_id, plugin_key, id);
CREATE INDEX idx_plugin_automation_runs_root ON plugin_automation_runs(tenant_id, root_run_id);
CREATE TABLE agent_proposals (
                id                      INTEGER    NOT NULL PRIMARY KEY,
                tenant_id               INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                agent_principal_id      TEXT  NOT NULL,
                on_behalf_of_profile_id INTEGER      NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                tool                    TEXT NOT NULL,
                arguments               TEXT        NOT NULL DEFAULT '{}',
                diff                    TEXT,
                scope                   TEXT        NOT NULL DEFAULT '[]',
                permissions             TEXT        NOT NULL DEFAULT '[]',
                summary                 TEXT         NOT NULL DEFAULT '',
                undo_window_seconds     INTEGER,
                status                  TEXT  NOT NULL DEFAULT 'waiting',
                result                  TEXT,
                decided_by_profile_id   INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                decided_at              TEXT,
                expires_at              TEXT    NOT NULL,
                created_at              TEXT NOT NULL DEFAULT (datetime('now'))
            , decline_reason TEXT, arguments_hash TEXT);
CREATE INDEX idx_agent_proposals_inbox ON agent_proposals(tenant_id, on_behalf_of_profile_id, status, id);
CREATE TABLE agents (
                id                     INTEGER    NOT NULL PRIMARY KEY,
                tenant_id              INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                slug                   TEXT  NOT NULL,
                name                   TEXT  NOT NULL,
                name_ar                TEXT  NOT NULL DEFAULT '',
                role                   TEXT NOT NULL DEFAULT '',
                role_ar                TEXT NOT NULL DEFAULT '',
                instructions           TEXT         NOT NULL DEFAULT '',
                instructions_ar        TEXT         NOT NULL DEFAULT '',
                tone                   TEXT  NOT NULL DEFAULT 'plain',
                language               TEXT   NOT NULL DEFAULT 'auto',
                toolsets               TEXT        NOT NULL DEFAULT '[]',
                grant_template         TEXT        NOT NULL DEFAULT '{}',
                preset_key             TEXT,
                preset_version         INTEGER,
                status                 TEXT  NOT NULL DEFAULT 'active',
                created_by_profile_id  INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                updated_by_profile_id  INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                created_at             TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at             TEXT NOT NULL DEFAULT (datetime('now')), paused_at TEXT, paused_by_profile_id INTEGER REFERENCES profiles(id) ON DELETE SET NULL, may_read TEXT NOT NULL DEFAULT '[]', features TEXT NOT NULL DEFAULT '{}', notify_by_email INTEGER NOT NULL DEFAULT 1,
                CONSTRAINT uq_agents_tenant_slug UNIQUE (tenant_id, slug)
            );
CREATE TABLE agent_assignments (
                id                     INTEGER   NOT NULL PRIMARY KEY,
                tenant_id              INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                agent_id               BIGINT      NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
                profile_id             INTEGER     NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                grant_modes            TEXT       NOT NULL DEFAULT '{}',
                revoked_at             TEXT,
                updated_by_profile_id  INTEGER     REFERENCES profiles(id) ON DELETE SET NULL,
                created_at             TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at             TEXT NOT NULL DEFAULT (datetime('now')), last_active_at TEXT,
                CONSTRAINT uq_agent_assignments_agent_profile UNIQUE (agent_id, profile_id)
            );
CREATE INDEX idx_agent_assignments_person ON agent_assignments(tenant_id, profile_id);
CREATE TABLE agent_actions (
                id                      INTEGER    NOT NULL PRIMARY KEY,
                tenant_id               INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                agent_principal_id      TEXT  NOT NULL,
                on_behalf_of_profile_id INTEGER      NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                proposal_id             BIGINT       REFERENCES agent_proposals(id) ON DELETE SET NULL,
                tool                    TEXT NOT NULL,
                arguments               TEXT        NOT NULL DEFAULT '{}',
                summary                 TEXT         NOT NULL DEFAULT '',
                permissions             TEXT        NOT NULL DEFAULT '[]',
                inverse                 TEXT,
                undo_window_seconds     INTEGER,
                undoable_until          TEXT,
                status                  TEXT  NOT NULL DEFAULT 'done',
                undone_by_profile_id    INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                undone_at               TEXT,
                undo_result             TEXT,
                created_at              TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_agent_actions_person ON agent_actions(tenant_id, on_behalf_of_profile_id, id);
CREATE INDEX idx_agent_actions_proposal ON agent_actions(proposal_id);
CREATE TABLE document_suggestions (
