                decided_by_profile_id   INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                decided_at              TEXT,
                created_at              TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at              TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_document_suggestions_source ON document_suggestions(tenant_id, source_id, status, id);
CREATE INDEX idx_document_suggestions_updated ON document_suggestions(tenant_id, source_id, updated_at);
CREATE TABLE document_comment_threads (
