                updated_at             TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_document_comment_threads_source ON document_comment_threads(tenant_id, source_id, id);
CREATE INDEX idx_document_comment_threads_updated ON document_comment_threads(tenant_id, source_id, updated_at);
CREATE TABLE document_comments (
                id                      INTEGER    NOT NULL PRIMARY KEY,
                tenant_id               INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                thread_id               BIGINT       NOT NULL REFERENCES document_comment_threads(id) ON DELETE CASCADE,
                created_by_profile_id   INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                actor_kind              TEXT  NOT NULL DEFAULT 'person',
                agent_principal_id      TEXT,
                on_behalf_of_profile_id INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                body                    TEXT        NOT NULL,
                mentions                TEXT        NOT NULL DEFAULT '[]',
