                UNIQUE (role_id, plugin_key)
            );
CREATE TABLE workspace_signup_settings (
                tenant_id       INTEGER      NOT NULL PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
                mode            TEXT  NOT NULL DEFAULT 'off',
