                allowed_domains TEXT         NOT NULL DEFAULT '[]',
                updated_by      INTEGER      NULL,
                updated_at      TEXT NOT NULL DEFAULT (datetime('now')), customer_invites INTEGER NOT NULL DEFAULT 0,
                CHECK (mode IN ('off', 'approval', 'open'))
            );
CREATE TABLE customer_signups (
                id            INTEGER    NOT NULL PRIMARY KEY,
                tenant_id     INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                email         TEXT NOT NULL,
                display_name  TEXT NOT NULL,
                token_hash    CHAR(64)     NULL UNIQUE,
                status        TEXT  NOT NULL DEFAULT 'unverified',
                profile_id    INTEGER      NULL REFERENCES profiles(id) ON DELETE CASCADE,
                expires_at    TEXT    NOT NULL,
                verified_at   TEXT    NULL,
                decided_at    TEXT    NULL,
                decided_by    INTEGER      NULL,
                created_at    TEXT NOT NULL DEFAULT (datetime('now')), contact_id INTEGER REFERENCES contacts(id) ON DELETE SET NULL,
                CHECK (status IN ('unverified', 'pending', 'approved', 'rejected', 'joined', 'superseded'))
            );
CREATE INDEX idx_customer_signups_tenant_status ON customer_signups (tenant_id, status);
CREATE INDEX idx_customer_signups_tenant_email ON customer_signups (tenant_id, email);
CREATE INDEX idx_document_routes_tenant_subject
                ON document_routes(tenant_id, subject_type, subject_id, id);
CREATE TABLE localized_texts (
                id            INTEGER    NOT NULL PRIMARY KEY,
