                field         TEXT  NOT NULL,
                language_code TEXT  NOT NULL,
                value         TEXT         NOT NULL,
                created_at    TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at    TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (entity_type, entity_id, field, language_code)
            );
CREATE INDEX idx_localized_texts_tenant ON localized_texts (tenant_id, entity_type, entity_id);
CREATE TABLE route_subject_versions (
                id           INTEGER    NOT NULL PRIMARY KEY,
                tenant_id    INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                subject_type TEXT  NOT NULL,
                subject_id   BIGINT       NOT NULL,
                version      INTEGER      NOT NULL,
                content_hash TEXT  NOT NULL,
                data         TEXT         NOT NULL,
                created_by   INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                created_at   TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (tenant_id, subject_type, subject_id, version)
            );
CREATE TABLE plugin_agent_context_grants (
                id                    INTEGER       PRIMARY KEY,
                plugin_name           TEXT NOT NULL UNIQUE,
                granted_by_profile_id INTEGER      NULL REFERENCES profiles(id) ON DELETE SET NULL,
                granted_at            TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE plugin_starter_seeds (
                id            INTEGER PRIMARY KEY,
                tenant_id     BIGINT       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                plugin        TEXT  NOT NULL,
                starter       TEXT  NOT NULL,
                source_id     BIGINT,
                content_hash  TEXT  NOT NULL,
                created_at    TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
                updated_at    TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
                UNIQUE (tenant_id, plugin, starter)
            );
CREATE TABLE document_issue_batches (
                id                 INTEGER    PRIMARY KEY,
                tenant_id          BIGINT       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                owner              TEXT  NOT NULL,
                batch_key          TEXT NOT NULL,
                request_hash       TEXT  NOT NULL,
                actor_profile_id   INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                actor_plugin       TEXT,
                actor_permissions  TEXT,
                template_slot      TEXT,
                -- @reference-lint-ignore: the template the sender asked for, resolved for each item when it runs; an unknown or deleted one is refused per item, and the record keeps the id
                template_source_id BIGINT,
                render             TEXT   NOT NULL DEFAULT 'auto',
                status             TEXT  NOT NULL DEFAULT 'queued'
                                   CHECK (status IN ('queued', 'running', 'done', 'cancelled')),
                total              INTEGER      NOT NULL DEFAULT 0,
                issued             INTEGER      NOT NULL DEFAULT 0,
                replayed           INTEGER      NOT NULL DEFAULT 0,
                refused            INTEGER      NOT NULL DEFAULT 0,
                failed             INTEGER      NOT NULL DEFAULT 0,
                cancelled          INTEGER      NOT NULL DEFAULT 0,
                backoffs           INTEGER      NOT NULL DEFAULT 0,
                created_at         TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
                updated_at         TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
                finished_at        TEXT,
                UNIQUE (tenant_id, owner, batch_key)
            );
CREATE TABLE document_issue_batch_items (
                id           INTEGER    PRIMARY KEY,
                tenant_id    BIGINT       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                batch_id     BIGINT       NOT NULL REFERENCES document_issue_batches(id) ON DELETE CASCADE,
                position     INTEGER      NOT NULL,
                record       TEXT,
                field_values TEXT,
                title        TEXT,
                origin_key   TEXT NOT NULL,
                status       TEXT  NOT NULL DEFAULT 'pending'
                             CHECK (status IN ('pending', 'issued', 'replayed', 'refused', 'failed', 'cancelled')),
                document_id  BIGINT       REFERENCES documents(id) ON DELETE SET NULL,
                reason       TEXT,
                message      TEXT,
                updated_at   TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
                UNIQUE (batch_id, position)
            );
CREATE INDEX idx_document_issue_batch_items_pending ON document_issue_batch_items(tenant_id, batch_id, status, position);
CREATE UNIQUE INDEX uq_document_route_events_chain
                ON document_route_events(tenant_id, document_id, prev_hash)
             WHERE prev_hash IS NOT NULL;
CREATE TABLE route_signatures (
                id                INTEGER    NOT NULL PRIMARY KEY,
                tenant_id         INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                document_id       BIGINT       NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
                route_id          BIGINT       NOT NULL REFERENCES document_routes(id) ON DELETE CASCADE,
                event_id          BIGINT       NOT NULL REFERENCES document_route_events(id),
                step_id           BIGINT       NOT NULL,
                subject_type      TEXT  NOT NULL,
                subject_id        BIGINT       NOT NULL,
                subject_version   INTEGER      NOT NULL,
                content_hash      TEXT  NOT NULL,
                -- @reference-lint-ignore: who signed, a fact of a legal record that outlives the profile; the seal covers it and signer_name and signer_email keep the person, so it has no foreign key to clear it
                signer_profile_id INTEGER      NOT NULL,
                signer_name       TEXT NOT NULL,
                signer_email      TEXT,
                capacity          TEXT,
                on_behalf_of      TEXT,
                confirmed_by      TEXT  NOT NULL
                    CHECK (confirmed_by IN ('totp', 'passkey', 'email_code', 'fresh_sign_in')),
                signed_at         TEXT    NOT NULL,
                ip_address        TEXT,
                user_agent        TEXT,
                consent_version   TEXT  NOT NULL,
                appearance        TEXT         NOT NULL,
                appearance_hash   TEXT  NOT NULL,
                record_hash       TEXT  NOT NULL,
                seal              TEXT         NOT NULL,
                seal_key_id       TEXT  NOT NULL,
                UNIQUE (event_id)
            );
CREATE INDEX idx_route_signatures_tenant_document
                ON route_signatures(tenant_id, document_id, id);
CREATE INDEX idx_route_signatures_tenant_subject
                ON route_signatures(tenant_id, subject_type, subject_id, subject_version);
CREATE TABLE saved_signatures (
                id         INTEGER NOT NULL PRIMARY KEY,
                tenant_id  INTEGER   NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                profile_id INTEGER   NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                appearance TEXT      NOT NULL,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (tenant_id, profile_id)
            );
CREATE TABLE signing_challenges (
                id          INTEGER   NOT NULL PRIMARY KEY,
                tenant_id   INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                profile_id  INTEGER     NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                method      TEXT NOT NULL CHECK (method IN ('email_code', 'fresh_sign_in')),
                route_id    BIGINT,
                content_hash TEXT,
                code_hash   TEXT,
                attempts    INTEGER     NOT NULL DEFAULT 0,
                expires_at  TEXT   NOT NULL,
                consumed_at TEXT,
                created_at  TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_signing_challenges_tenant_profile
                ON signing_challenges(tenant_id, profile_id, method, id);
CREATE TABLE instance_signing_keys (
                id         INTEGER      NOT NULL PRIMARY KEY,
                -- @reference-lint-ignore: this key's own public name, not a reference to another row
                key_id     TEXT NOT NULL UNIQUE,
                algorithm  TEXT NOT NULL DEFAULT 'Ed25519',
                public_key TEXT NOT NULL,
                secret_key TEXT        NOT NULL,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                retired_at TEXT
            );
CREATE UNIQUE INDEX uq_document_route_events_route_chain
                ON document_route_events(tenant_id, route_id, prev_hash)
             WHERE document_id IS NULL AND prev_hash IS NOT NULL;
CREATE TABLE route_finalisations (
                id              INTEGER    NOT NULL PRIMARY KEY,
                tenant_id       INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                route_id        BIGINT       NOT NULL REFERENCES document_routes(id) ON DELETE CASCADE,
                step_id         BIGINT       NOT NULL REFERENCES document_route_steps(id) ON DELETE CASCADE,
                subject_type    TEXT  NOT NULL,
                subject_id      BIGINT       NOT NULL,
                template_id     BIGINT,
                subject_version INTEGER,
                content_hash    TEXT,
                status          TEXT  NOT NULL DEFAULT 'waiting'
                                CHECK (status IN ('waiting', 'done', 'failed')),
                reason          TEXT,
                document_id     BIGINT       REFERENCES documents(id) ON DELETE SET NULL,
                artifact_id     BIGINT       REFERENCES document_artifacts(id) ON DELETE SET NULL,
                attempts        INTEGER      NOT NULL DEFAULT 0,
                attempt_started_at TEXT,
                claim_token     TEXT,
                reached_at      TEXT NOT NULL DEFAULT (datetime('now')),
                finalised_at    TEXT,
                UNIQUE (route_id)
            );
CREATE INDEX idx_route_finalisations_subject
                ON route_finalisations(tenant_id, subject_type, subject_id);
CREATE TABLE tenant_plan_addons (
                tenant_id   INTEGER   NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                plan_id     BIGINT    NOT NULL REFERENCES plans(id) ON DELETE RESTRICT,
                quantity    INTEGER   NOT NULL DEFAULT 1,
                assigned_by INTEGER   NULL,
                assigned_at TEXT NOT NULL DEFAULT (datetime('now')),
                PRIMARY KEY (tenant_id, plan_id),
                CHECK (quantity > 0)
            );
CREATE INDEX idx_tenant_plan_addons_plan ON tenant_plan_addons (plan_id);
CREATE TABLE tenant_monthly_customers (
                tenant_id     INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                period        CHAR(7)     NOT NULL,
                customer_ref  TEXT NOT NULL,
                first_seen_at TEXT NOT NULL DEFAULT (datetime('now')),
                PRIMARY KEY (tenant_id, period, customer_ref)
            );
CREATE TABLE conversations (
                id                  INTEGER PRIMARY KEY,
                tenant_id           INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                channel             TEXT NOT NULL,
                subject             TEXT,
                status              TEXT  NOT NULL DEFAULT 'open',
                assigned_profile_id INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                customer_profile_id INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                contact_name        TEXT,
                contact_address     TEXT NOT NULL,
                last_message_at     TEXT NOT NULL DEFAULT (datetime('now')),
                last_inbound_at     TEXT,
                created_at          TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at          TEXT NOT NULL DEFAULT (datetime('now')),
                closed_at           TEXT, kind TEXT NOT NULL DEFAULT 'customer',
                CONSTRAINT conversations_status_check CHECK (status IN ('open', 'pending', 'closed'))
            );
CREATE INDEX conversations_inbox_idx ON conversations (tenant_id, status, last_message_at DESC, id DESC);
CREATE INDEX conversations_contact_idx ON conversations (tenant_id, channel, contact_address);
CREATE INDEX conversations_assignee_idx ON conversations (tenant_id, assigned_profile_id, status);
CREATE INDEX conversations_customer_idx ON conversations (tenant_id, customer_profile_id);
CREATE TABLE messages (
                id                INTEGER PRIMARY KEY,
                tenant_id         INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                conversation_id   BIGINT       NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
                kind              TEXT  NOT NULL,
                author_profile_id INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                by_agent          INTEGER      NOT NULL DEFAULT 0,
                source            TEXT,
                body_text         TEXT         NOT NULL,
                body_html         TEXT,
                external_id       TEXT,
                in_reply_to       TEXT,
                status            TEXT  NOT NULL,
                status_detail     TEXT,
                attachments_not_shown INTEGER  NOT NULL DEFAULT 0,
                send_after        TEXT,
                sent_at           TEXT,
                created_at        TEXT NOT NULL DEFAULT (datetime('now')), chat_meta TEXT, reply_to_message_id BIGINT REFERENCES messages(id) ON DELETE SET NULL, thread_root_id BIGINT REFERENCES messages(id) ON DELETE CASCADE, in_chat INTEGER NOT NULL DEFAULT 1, edited_at TEXT, deleted_at TEXT, pinned_at TEXT, pinned_by_profile_id INTEGER REFERENCES profiles(id) ON DELETE SET NULL, changed_at TEXT, channel TEXT, channel_address TEXT,
                CONSTRAINT messages_kind_check CHECK (kind IN ('inbound', 'outbound', 'note')),
                CONSTRAINT messages_status_check CHECK (status IN ('received', 'queued', 'sent', 'delivered', 'read', 'failed', 'cancelled', 'noted'))
            );
CREATE INDEX messages_conversation_idx ON messages (tenant_id, conversation_id, id);
CREATE INDEX messages_external_idx ON messages (tenant_id, external_id);
CREATE UNIQUE INDEX messages_external_unique ON messages (tenant_id, conversation_id, external_id) WHERE external_id IS NOT NULL;
CREATE TABLE webchat_visitors (
                id              INTEGER PRIMARY KEY,
                tenant_id       INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                conversation_id BIGINT       NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
                token_hash      CHAR(64)     NOT NULL,
                profile_id      INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                display_name    TEXT,
                email           TEXT,
                ip_hash         CHAR(64),
                created_at      TEXT NOT NULL DEFAULT (datetime('now')),
                last_seen_at    TEXT NOT NULL DEFAULT (datetime('now'))
            , contact_id INTEGER REFERENCES contacts(id) ON DELETE SET NULL);
CREATE UNIQUE INDEX webchat_visitors_token_unique ON webchat_visitors (token_hash);
CREATE INDEX webchat_visitors_ip_idx ON webchat_visitors (tenant_id, ip_hash, created_at);
CREATE TABLE calendar_staff (
                id              INTEGER PRIMARY KEY,
                tenant_id       INTEGER      NOT NULL REFERENCES tenants(id)  ON DELETE CASCADE,
                profile_id      INTEGER      NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                bookable        INTEGER      NOT NULL DEFAULT 1,
                sort_order      INTEGER      NOT NULL DEFAULT 0,
                feed_token_hash CHAR(64),
                created_at      TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at      TEXT NOT NULL DEFAULT (datetime('now')), unit_id INTEGER REFERENCES organizational_units(id) ON DELETE SET NULL,
                UNIQUE (tenant_id, profile_id)
            );
CREATE UNIQUE INDEX idx_calendar_staff_feed_token ON calendar_staff(feed_token_hash);
CREATE TABLE calendar_working_hours (
                id          INTEGER PRIMARY KEY,
                tenant_id   INTEGER     NOT NULL REFERENCES tenants(id)  ON DELETE CASCADE,
                profile_id  INTEGER     NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                weekday     SMALLINT    NOT NULL,
                start_time  CHAR(5)     NOT NULL,
                end_time    CHAR(5)     NOT NULL,
                created_at  TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_calendar_working_hours_owner ON calendar_working_hours(tenant_id, profile_id);
CREATE TABLE calendar_events (
                id            INTEGER PRIMARY KEY,
                tenant_id     INTEGER      NOT NULL REFERENCES tenants(id)  ON DELETE CASCADE,
                profile_id    INTEGER      NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                title         TEXT NOT NULL,
                notes         TEXT         NOT NULL DEFAULT '',
                starts_at     TEXT    NOT NULL,
                ends_at       TEXT    NOT NULL,
                all_day       INTEGER      NOT NULL DEFAULT 0,
                busy          INTEGER      NOT NULL DEFAULT 1,
                status        TEXT  NOT NULL DEFAULT 'confirmed',
                external_ref  TEXT,
                created_by_profile_id INTEGER REFERENCES profiles(id) ON DELETE SET NULL,
                created_at    TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
            , kind TEXT NOT NULL DEFAULT 'event', room_id INTEGER REFERENCES calendar_rooms(id) ON DELETE SET NULL, location TEXT NOT NULL DEFAULT '', meeting_id BIGINT REFERENCES meetings(id) ON DELETE SET NULL, legacy_ref TEXT, ics_uid TEXT, ics_sequence INTEGER NOT NULL DEFAULT 0, reminder_due_at TEXT, reminder_sent_at TEXT);
CREATE INDEX idx_calendar_events_owner ON calendar_events(tenant_id, profile_id, starts_at);
CREATE TABLE calendar_services (
                id                    INTEGER PRIMARY KEY,
                tenant_id             INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                name                  TEXT        NOT NULL,
                description           TEXT        NOT NULL DEFAULT '{}',
                duration_minutes      INTEGER     NOT NULL,
                buffer_before_minutes INTEGER     NOT NULL DEFAULT 0,
                buffer_after_minutes  INTEGER     NOT NULL DEFAULT 0,
                price_minor           BIGINT,
                currency              CHAR(3)     NOT NULL DEFAULT 'JOD',
                bookable_online       INTEGER     NOT NULL DEFAULT 1,
                active                INTEGER     NOT NULL DEFAULT 1,
                sort_order            INTEGER     NOT NULL DEFAULT 0,
                created_at            TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at            TEXT NOT NULL DEFAULT (datetime('now'))
            , room_id INTEGER REFERENCES calendar_rooms(id) ON DELETE SET NULL, needs_approval INTEGER NOT NULL DEFAULT 0);
CREATE INDEX idx_calendar_services_tenant_id ON calendar_services(tenant_id);
CREATE TABLE calendar_service_staff (
                id          INTEGER PRIMARY KEY,
                tenant_id   INTEGER   NOT NULL REFERENCES tenants(id)           ON DELETE CASCADE,
                service_id  INTEGER   NOT NULL REFERENCES calendar_services(id) ON DELETE CASCADE,
                profile_id  INTEGER   NOT NULL REFERENCES profiles(id)          ON DELETE CASCADE,
                created_at  TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (tenant_id, service_id, profile_id)
            );
CREATE TABLE calendar_bookings (
                id                      INTEGER PRIMARY KEY,
                tenant_id               INTEGER      NOT NULL REFERENCES tenants(id)           ON DELETE CASCADE,
                service_id              INTEGER      NOT NULL REFERENCES calendar_services(id) ON DELETE RESTRICT,
                profile_id              INTEGER      NOT NULL REFERENCES profiles(id)          ON DELETE RESTRICT,
                customer_profile_id     INTEGER               REFERENCES profiles(id)          ON DELETE SET NULL,
                customer_name           TEXT NOT NULL,
                customer_email          TEXT NOT NULL DEFAULT '',
                customer_phone          TEXT  NOT NULL DEFAULT '',
                customer_note           TEXT NOT NULL DEFAULT '',
                starts_at               TEXT    NOT NULL,
                ends_at                 TEXT    NOT NULL,
                blocks_from             TEXT    NOT NULL,
                blocks_until            TEXT    NOT NULL,
                status                  TEXT  NOT NULL,
                hold_expires_at         TEXT,
                source                  TEXT  NOT NULL,
                price_minor             BIGINT,
                currency                CHAR(3)      NOT NULL DEFAULT 'JOD',
                payment_ref             TEXT,
                manage_token_hash       CHAR(64),
                manage_token_expires_at TEXT,
                reminder_due_at         TEXT,
                reminder_sent_at        TEXT,
                created_by_profile_id   INTEGER               REFERENCES profiles(id) ON DELETE SET NULL,
                cancelled_by            TEXT,
                cancel_reason           TEXT NOT NULL DEFAULT '',
                cancelled_at            TEXT,
                created_at              TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at              TEXT NOT NULL DEFAULT (datetime('now'))
            , room_id INTEGER REFERENCES calendar_rooms(id) ON DELETE SET NULL, checked_in_at TEXT, suggested_at TEXT, ics_sequence INTEGER NOT NULL DEFAULT 0, contact_id INTEGER REFERENCES contacts(id) ON DELETE SET NULL);
CREATE INDEX idx_calendar_bookings_owner ON calendar_bookings(tenant_id, profile_id, blocks_from);
CREATE INDEX idx_calendar_bookings_starts ON calendar_bookings(tenant_id, starts_at);
CREATE UNIQUE INDEX idx_calendar_bookings_manage_token ON calendar_bookings(manage_token_hash);
CREATE TABLE away_periods (
                id                  INTEGER    PRIMARY KEY,
                tenant_id           INTEGER      NOT NULL REFERENCES tenants(id)  ON DELETE CASCADE,
                profile_id          INTEGER      NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                delegate_profile_id INTEGER      NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                starts_on           DATE         NOT NULL,
                back_on             DATE         NOT NULL,
                covers              TEXT         NOT NULL,
                message             TEXT,
                ended_at            TEXT,
                created_at          TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at          TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_away_periods_tenant_profile ON away_periods (tenant_id, profile_id);
CREATE INDEX idx_away_periods_tenant_delegate ON away_periods (tenant_id, delegate_profile_id);
CREATE TABLE document_agent_requests (
                id                      INTEGER     NOT NULL PRIMARY KEY,
                tenant_id               INTEGER       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                source_id               BIGINT        NOT NULL REFERENCES document_sources(id) ON DELETE CASCADE,
                requested_by_profile_id INTEGER       NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                agent_principal_id      TEXT,
                claimed_by_principal_id TEXT,
                request                 TEXT          NOT NULL,
                anchor_block_id         TEXT,
                quote                   TEXT,
                status                  TEXT   NOT NULL DEFAULT 'queued',
                title                   TEXT,
                progress_done           INTEGER,
                progress_total          INTEGER,
                detail                  TEXT,
                stop_requested_at       TEXT,
                claimed_at              TEXT,
                finished_at             TEXT,
                created_at              TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at              TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_document_agent_requests_queue ON document_agent_requests(tenant_id, requested_by_profile_id, status, id);
CREATE INDEX idx_document_agent_requests_source ON document_agent_requests(tenant_id, source_id, id);
CREATE INDEX conversations_kind_idx ON conversations (tenant_id, kind, last_message_at DESC, id DESC);
CREATE TABLE chats (
                conversation_id       BIGINT       NOT NULL PRIMARY KEY REFERENCES conversations(id) ON DELETE CASCADE,
                tenant_id             INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                type                  TEXT  NOT NULL,
                direct_key            TEXT,
                link_type             TEXT,
                link_id               TEXT,
                link_label            TEXT,
                created_by_profile_id INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                created_at            TEXT NOT NULL DEFAULT (datetime('now')),
                CONSTRAINT chats_type_check CHECK (type IN ('group', 'direct')),
                CONSTRAINT chats_link_check CHECK (link_type IS NULL OR link_type IN ('board', 'meeting', 'record'))
            );
CREATE UNIQUE INDEX chats_direct_unique ON chats (tenant_id, direct_key) WHERE direct_key IS NOT NULL;
CREATE INDEX chats_link_idx ON chats (tenant_id, link_type, link_id);
CREATE TABLE chat_members (
                id                     INTEGER    PRIMARY KEY,
                tenant_id              INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                conversation_id        BIGINT       NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
                profile_id             INTEGER      REFERENCES profiles(id) ON DELETE CASCADE,
                agent_id               BIGINT       REFERENCES agents(id) ON DELETE CASCADE,
                works_for_profile_id   INTEGER      REFERENCES profiles(id) ON DELETE CASCADE,
                reads                  TEXT  NOT NULL DEFAULT 'all',
                -- @reference-lint-ignore: a position in the chat's message ids (read from after it), not a message; 0 means from the start
                reads_after_message_id BIGINT       NOT NULL DEFAULT 0,
                actions                TEXT        NOT NULL DEFAULT '{}',
                added_by_profile_id    INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                -- @reference-lint-ignore: a read mark, a position in the chat's message ids, not a message; it stays valid when that message is gone
                last_read_message_id   BIGINT       NOT NULL DEFAULT 0,
                joined_at              TEXT NOT NULL DEFAULT (datetime('now')),
                removed_at             TEXT,
                CONSTRAINT chat_members_who_check CHECK (
                    (profile_id IS NOT NULL AND agent_id IS NULL)
                    OR (agent_id IS NOT NULL AND profile_id IS NULL AND works_for_profile_id IS NOT NULL)
                ),
                CONSTRAINT chat_members_reads_check CHECK (reads IN ('now', 'week', 'all'))
            );
CREATE UNIQUE INDEX chat_members_person_unique ON chat_members (conversation_id, profile_id) WHERE profile_id IS NOT NULL AND removed_at IS NULL;
CREATE UNIQUE INDEX chat_members_agent_unique ON chat_members (conversation_id, agent_id) WHERE agent_id IS NOT NULL AND removed_at IS NULL;
CREATE INDEX chat_members_profile_idx ON chat_members (tenant_id, profile_id);
CREATE INDEX chat_members_agent_idx ON chat_members (tenant_id, agent_id, works_for_profile_id);
CREATE TABLE calendar_rooms (
                id          INTEGER PRIMARY KEY,
                tenant_id   INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                name        TEXT        NOT NULL,
                unit_id     INTEGER              REFERENCES organizational_units(id) ON DELETE SET NULL,
                active      INTEGER     NOT NULL DEFAULT 1,
                sort_order  INTEGER     NOT NULL DEFAULT 0,
                created_at  TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at  TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_calendar_rooms_tenant_id ON calendar_rooms(tenant_id);
CREATE INDEX idx_calendar_bookings_room ON calendar_bookings(tenant_id, room_id, blocks_from);
CREATE TABLE saved_blocks (
                id                 INTEGER     NOT NULL PRIMARY KEY,
                tenant_id          INTEGER       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                name               TEXT  NOT NULL,
                description        TEXT,
                mode               TEXT   NOT NULL,
                sharing            TEXT   NOT NULL DEFAULT 'me',
                owner_profile_id   INTEGER       REFERENCES profiles(id) ON DELETE SET NULL,
                blocks             TEXT         NOT NULL,
                per_document_keys  TEXT         NOT NULL DEFAULT '[]',
                version            INTEGER       NOT NULL DEFAULT 1,
                archived_at        TEXT,
                created_at         TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at         TEXT NOT NULL DEFAULT (datetime('now')), per_document_parts TEXT NOT NULL DEFAULT '[]',
                CHECK (mode IN ('synced', 'copy')),
                CHECK (sharing IN ('me', 'workspace'))
            );
CREATE INDEX idx_saved_blocks_tenant ON saved_blocks(tenant_id, archived_at, sharing, owner_profile_id);
CREATE TABLE saved_block_versions (
                id              INTEGER  NOT NULL PRIMARY KEY,
                tenant_id       INTEGER    NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                saved_block_id  BIGINT     NOT NULL REFERENCES saved_blocks(id) ON DELETE CASCADE,
                version         INTEGER    NOT NULL,
                blocks          TEXT      NOT NULL,
                created_at      TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (saved_block_id, version)
            );
CREATE INDEX idx_saved_block_versions_tenant ON saved_block_versions(tenant_id, saved_block_id, version);
CREATE TABLE contacts (
                id                    INTEGER PRIMARY KEY,
                tenant_id             INTEGER       NOT NULL REFERENCES tenants(id)  ON DELETE CASCADE,
                is_customer           INTEGER       NOT NULL DEFAULT 1,
                is_supplier           INTEGER       NOT NULL DEFAULT 0,
                name                  TEXT  NOT NULL,
                contact_person        TEXT  NOT NULL DEFAULT '',
                email                 TEXT  NOT NULL DEFAULT '',
                mobile                TEXT   NOT NULL DEFAULT '',
                phone                 TEXT   NOT NULL DEFAULT '',
                tax_number            TEXT   NOT NULL DEFAULT '',
                payment_terms         TEXT  NOT NULL DEFAULT '',
                address               TEXT NOT NULL DEFAULT '',
                notes                 TEXT NOT NULL DEFAULT '',
                profile_id            INTEGER                REFERENCES profiles(id) ON DELETE SET NULL,
                created_by_profile_id INTEGER                REFERENCES profiles(id) ON DELETE SET NULL,
                archived_at           TEXT,
                created_at            TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at            TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_contacts_tenant_name ON contacts(tenant_id, name);
CREATE INDEX idx_contacts_tenant_mobile ON contacts(tenant_id, mobile);
CREATE INDEX idx_contacts_tenant_tax ON contacts(tenant_id, tax_number);
CREATE INDEX idx_contacts_tenant_email ON contacts(tenant_id, email);
CREATE INDEX idx_contacts_tenant_profile ON contacts(tenant_id, profile_id);
CREATE TABLE contact_imports (
                id                    INTEGER PRIMARY KEY,
                tenant_id             INTEGER       NOT NULL REFERENCES tenants(id)  ON DELETE CASCADE,
                created_by_profile_id INTEGER                REFERENCES profiles(id) ON DELETE SET NULL,
                file_name             TEXT  NOT NULL DEFAULT '',
                status                TEXT   NOT NULL DEFAULT 'uploaded',
                header_json           TEXT          NOT NULL,
                rows_json             TEXT          NOT NULL,
                options_json          TEXT          NOT NULL DEFAULT '{}',
                summary_json          TEXT          NOT NULL DEFAULT '{}',
                imported_at           TEXT,
                undone_at             TEXT,
                created_at            TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at            TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_contact_imports_tenant ON contact_imports(tenant_id, created_at);
CREATE TABLE contact_import_changes (
                id          INTEGER PRIMARY KEY,
                tenant_id   INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                import_id   INTEGER      NOT NULL REFERENCES contact_imports(id) ON DELETE CASCADE,
                -- @reference-lint-ignore: the contact an import made or changed; undo removes made ones itself, and a row for a contact deleted since is skipped
                contact_id  INTEGER      NOT NULL,
                action      TEXT  NOT NULL,
                before_json TEXT,
                tags_added  TEXT         NOT NULL DEFAULT '[]',
                created_at  TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_contact_import_changes_import ON contact_import_changes(tenant_id, import_id);
CREATE TABLE custom_field_definitions (
                id                    INTEGER PRIMARY KEY,
                tenant_id             INTEGER      NOT NULL REFERENCES tenants(id)  ON DELETE CASCADE,
                record_type           TEXT  NOT NULL,
                field_key             TEXT  NOT NULL,
                label                 TEXT         NOT NULL,
                kind                  TEXT  NOT NULL,
                options_json          TEXT         NOT NULL DEFAULT '[]',
                show_in_list          INTEGER      NOT NULL DEFAULT 0,
                is_required           INTEGER      NOT NULL DEFAULT 0,
                edit_permission       TEXT,
                sort_order            INTEGER      NOT NULL DEFAULT 0,
                created_by_profile_id INTEGER               REFERENCES profiles(id) ON DELETE SET NULL,
                archived_at           TEXT,
                created_at            TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at            TEXT NOT NULL DEFAULT (datetime('now')), owner_plugin TEXT,
                UNIQUE (tenant_id, record_type, field_key)
            );
CREATE TABLE custom_field_values (
                id          INTEGER PRIMARY KEY,
                tenant_id   INTEGER       NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                field_id    INTEGER       NOT NULL REFERENCES custom_field_definitions(id) ON DELETE CASCADE,
                record_type TEXT   NOT NULL,
                record_id   INTEGER       NOT NULL,
                value_json  TEXT          NOT NULL,
                value_text  TEXT NOT NULL DEFAULT '',
