CREATE TABLE chat_person_state (
                tenant_id            INTEGER   NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                conversation_id      BIGINT    NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
                profile_id           INTEGER   NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                pinned_at            TEXT,
                -- @reference-lint-ignore: a read mark, a position in the conversation's message ids, not a message
                last_read_message_id BIGINT    NOT NULL DEFAULT 0,
                updated_at           TEXT NOT NULL DEFAULT (datetime('now')), muted INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (conversation_id, profile_id)
            );
CREATE INDEX chat_person_state_profile_idx ON chat_person_state (tenant_id, profile_id);
CREATE INDEX messages_thread_idx ON messages (tenant_id, thread_root_id, id) WHERE thread_root_id IS NOT NULL;
CREATE INDEX messages_changed_idx ON messages (tenant_id, conversation_id, changed_at) WHERE changed_at IS NOT NULL;
CREATE INDEX messages_pinned_idx ON messages (tenant_id, conversation_id) WHERE pinned_at IS NOT NULL;
CREATE TABLE chat_message_reactions (
                tenant_id   INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                message_id  BIGINT      NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
                profile_id  INTEGER     NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                emoji       TEXT NOT NULL,
                created_at  TEXT NOT NULL DEFAULT (datetime('now')),
                PRIMARY KEY (message_id, profile_id, emoji)
            );
CREATE INDEX chat_message_reactions_tenant_idx ON chat_message_reactions (tenant_id, message_id);
CREATE TABLE chat_bots (
                tenant_id             INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                kind                  TEXT NOT NULL,
                enabled               INTEGER     NOT NULL DEFAULT 0,
                settings              TEXT        NOT NULL DEFAULT '{}',
                updated_by_profile_id INTEGER     REFERENCES profiles(id) ON DELETE SET NULL,
                updated_at            TEXT NOT NULL DEFAULT (datetime('now')),
                PRIMARY KEY (tenant_id, kind),
                CONSTRAINT chat_bots_kind_check CHECK (kind IN ('away', 'welcome', 'handover'))
            );
CREATE TABLE chat_blocked_senders (
                id                    INTEGER    PRIMARY KEY,
                tenant_id             INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                channel               TEXT NOT NULL,
                address               TEXT NOT NULL,
                address_key           TEXT NOT NULL,
                name                  TEXT,
                reported_spam         INTEGER      NOT NULL DEFAULT 0,
                blocked_by_profile_id INTEGER      REFERENCES profiles(id) ON DELETE SET NULL,
                created_at            TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE UNIQUE INDEX chat_blocked_senders_unique ON chat_blocked_senders (tenant_id, channel, address_key);
CREATE UNIQUE INDEX idx_calendar_events_legacy_ref ON calendar_events(tenant_id, legacy_ref) WHERE legacy_ref IS NOT NULL;
CREATE UNIQUE INDEX idx_calendar_events_meeting ON calendar_events(meeting_id) WHERE meeting_id IS NOT NULL;
CREATE INDEX idx_calendar_events_room ON calendar_events(tenant_id, room_id, starts_at);
CREATE INDEX idx_calendar_events_range ON calendar_events(tenant_id, starts_at);
CREATE TABLE calendar_event_people (
                id           INTEGER PRIMARY KEY,
                tenant_id    INTEGER     NOT NULL REFERENCES tenants(id)          ON DELETE CASCADE,
                event_id     INTEGER     NOT NULL REFERENCES calendar_events(id)  ON DELETE CASCADE,
                profile_id   INTEGER     NOT NULL REFERENCES profiles(id)         ON DELETE CASCADE,
                role         TEXT NOT NULL DEFAULT 'required',
                response     TEXT NOT NULL DEFAULT 'invited',
                responded_at TEXT,
                created_at   TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (event_id, profile_id)
            );
CREATE INDEX idx_calendar_event_people_person ON calendar_event_people(tenant_id, profile_id);
CREATE TABLE tenant_code_plugins (
                tenant_id             INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                plugin_name           TEXT NOT NULL,
                enabled               INTEGER     NOT NULL DEFAULT 0,
                trial_started_at      TEXT   NULL,
                trial_ends_at         TEXT   NULL,
                access_lapsed_at      TEXT   NULL,
                changed_by_profile_id INTEGER     NULL REFERENCES profiles(id) ON DELETE SET NULL,
                changed_at            TEXT NOT NULL DEFAULT (datetime('now')),
                PRIMARY KEY (tenant_id, plugin_name)
            );
CREATE INDEX idx_tenant_code_plugins_plugin ON tenant_code_plugins (plugin_name);
CREATE TABLE code_plugin_access (
                plugin_name           TEXT NOT NULL PRIMARY KEY,
                workspace_access      TEXT NOT NULL DEFAULT 'choose'
                                      CHECK (workspace_access IN ('all', 'choose', 'operator')),
                free_for_all          INTEGER     NOT NULL DEFAULT 0,
                updated_by_profile_id INTEGER     NULL REFERENCES profiles(id) ON DELETE SET NULL,
                updated_at            TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX messages_channel_idx ON messages (tenant_id, conversation_id, channel, id);
CREATE TABLE conversation_contacts (
                id              INTEGER PRIMARY KEY,
                tenant_id       INTEGER      NOT NULL REFERENCES tenants(id)       ON DELETE CASCADE,
                channel         TEXT NOT NULL,
                address_key     TEXT NOT NULL,
                conversation_id BIGINT       NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
                contact_id      INTEGER               REFERENCES contacts(id)      ON DELETE SET NULL,
                created_at      TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at      TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (tenant_id, channel, address_key)
            );
CREATE INDEX conversation_contacts_conversation_idx ON conversation_contacts (tenant_id, conversation_id);
CREATE INDEX conversation_contacts_contact_idx ON conversation_contacts (tenant_id, contact_id);
CREATE INDEX idx_calendar_bookings_contact ON calendar_bookings (tenant_id, contact_id);
CREATE INDEX idx_webchat_visitors_contact ON webchat_visitors (tenant_id, contact_id);
CREATE INDEX idx_customer_signups_contact ON customer_signups (tenant_id, contact_id);
CREATE TABLE plugin_cash_payments (
                id                    INTEGER    NOT NULL PRIMARY KEY,
                tenant_id             INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                plan_key              TEXT NOT NULL,
                quantity              INTEGER      NOT NULL DEFAULT 1,
                amount_minor          BIGINT       NOT NULL,
                currency              TEXT   NOT NULL,
                receipt_number        TEXT  NOT NULL,
                note                  TEXT         NULL,
                paid_on               DATE         NOT NULL,
                period_start          TEXT    NOT NULL,
                period_end            TEXT    NOT NULL,
                recorded_by_profile_id INTEGER     NULL REFERENCES profiles(id) ON DELETE SET NULL,
                recorded_at           TEXT NOT NULL DEFAULT (datetime('now')),
                voided_at             TEXT    NULL,
                voided_by_profile_id  INTEGER      NULL REFERENCES profiles(id) ON DELETE SET NULL,
                void_reason           TEXT         NULL,
                reminder_sent_at      TEXT    NULL,
                CHECK (quantity > 0),
                CHECK (amount_minor >= 0),
                CHECK (period_end > period_start)
            );
CREATE INDEX idx_plugin_cash_payments_tenant ON plugin_cash_payments (tenant_id, plan_key);
CREATE UNIQUE INDEX uq_plugin_cash_payments_receipt ON plugin_cash_payments (tenant_id, receipt_number);
CREATE TABLE stored_files (
                id                    INTEGER     PRIMARY KEY,
                tenant_id             INTEGER       NOT NULL REFERENCES tenants(id)  ON DELETE CASCADE,
                kind                  TEXT   NOT NULL,
                storage_key           TEXT  NOT NULL,
                content_type          TEXT  NOT NULL,
                byte_size             BIGINT        NOT NULL,
                checksum_sha256       TEXT,
                filename              TEXT,
                created_by_profile_id INTEGER       REFERENCES profiles(id) ON DELETE SET NULL,
                created_at            TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (tenant_id, storage_key)
            );
CREATE INDEX idx_stored_files_tenant_kind ON stored_files (tenant_id, kind, created_at);
CREATE TABLE "document_artifacts" (
    "id" INTEGER PRIMARY KEY,
    "tenant_id" INTEGER NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    "document_id" BIGINT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    "rendered_by" INTEGER REFERENCES profiles(id) ON DELETE SET NULL,
    "rendered_at" TEXT NOT NULL DEFAULT (datetime('now')),
    "pages" INTEGER,
    "stored_file_id" BIGINT REFERENCES stored_files(id) ON DELETE SET NULL
);
CREATE INDEX idx_document_artifacts_tenant_id ON document_artifacts(tenant_id);
CREATE INDEX idx_document_artifacts_tenant_document
                ON document_artifacts(tenant_id, document_id, id);
CREATE TABLE "form_uploads" (
    "id" INTEGER PRIMARY KEY,
    "tenant_id" INTEGER NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    "form_id" BIGINT NOT NULL REFERENCES forms(id) ON DELETE CASCADE,
    "uploaded_by_profile_id" INTEGER REFERENCES profiles(id) ON DELETE SET NULL,
    "created_at" TEXT NOT NULL DEFAULT (datetime('now')),
    "claimed_at" TEXT,
    "submission_id" BIGINT REFERENCES form_submissions(id) ON DELETE SET NULL,
    "stored_file_id" BIGINT REFERENCES stored_files(id) ON DELETE SET NULL
);
CREATE INDEX idx_form_uploads_tenant_form
                 ON form_uploads(tenant_id, form_id);
CREATE INDEX idx_form_uploads_unclaimed
                 ON form_uploads(created_at) WHERE claimed_at IS NULL;
CREATE TABLE "document_source_files" (
    "id" INTEGER PRIMARY KEY,
    "tenant_id" INTEGER NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    "source_id" BIGINT NOT NULL REFERENCES document_sources(id) ON DELETE CASCADE,
    "uploaded_by_profile_id" INTEGER REFERENCES profiles(id) ON DELETE SET NULL,
    "created_at" TEXT NOT NULL DEFAULT (datetime('now')),
    "stored_file_id" BIGINT REFERENCES stored_files(id) ON DELETE SET NULL
);
CREATE INDEX idx_document_source_files_tenant_source ON document_source_files(tenant_id, source_id);
CREATE TABLE "chat_attachments" (
    "id" INTEGER PRIMARY KEY,
    "tenant_id" INTEGER NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    "conversation_id" BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    "message_id" BIGINT REFERENCES messages(id) ON DELETE CASCADE,
    "uploaded_by_profile_id" INTEGER REFERENCES profiles(id) ON DELETE SET NULL,
    "kind" TEXT NOT NULL,
    "width" INTEGER,
    "height" INTEGER,
    "duration_ms" INTEGER,
    "transcript" TEXT,
    "created_at" TEXT NOT NULL DEFAULT (datetime('now')),
    "stored_file_id" BIGINT REFERENCES stored_files(id) ON DELETE SET NULL,
    CONSTRAINT chat_attachments_kind_check CHECK (kind IN ('image', 'video', 'file', 'voice'))
);
CREATE INDEX chat_attachments_message_idx ON chat_attachments (tenant_id, message_id);
CREATE INDEX chat_attachments_chat_idx ON chat_attachments (tenant_id, conversation_id, kind);
CREATE UNIQUE INDEX ux_document_artifacts_stored_file ON document_artifacts (stored_file_id);
CREATE UNIQUE INDEX ux_form_uploads_stored_file ON form_uploads (stored_file_id);
CREATE UNIQUE INDEX ux_document_source_files_stored_file ON document_source_files (stored_file_id);
CREATE TABLE workspace_owners (
                id                  INTEGER     PRIMARY KEY,
                tenant_id           INTEGER    NOT NULL REFERENCES tenants(id)  ON DELETE CASCADE,
                profile_id          INTEGER    NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                added_by_profile_id INTEGER             REFERENCES profiles(id) ON DELETE SET NULL,
                created_at          TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (tenant_id, profile_id)
            );
CREATE INDEX idx_workspace_owners_profile ON workspace_owners (profile_id);
CREATE TABLE workspace_ownership_offers (
                id                    INTEGER       PRIMARY KEY,
                tenant_id             INTEGER      NOT NULL REFERENCES tenants(id)  ON DELETE CASCADE,
                kind                  TEXT  NOT NULL CHECK (kind IN ('transfer', 'co_owner')),
                from_profile_id       INTEGER      NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                to_profile_id         INTEGER      NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                leave_after           INTEGER      NOT NULL DEFAULT 0,
                status                TEXT  NOT NULL DEFAULT 'open'
                                      CHECK (status IN ('open', 'accepted', 'declined', 'cancelled', 'expired', 'void')),
                expires_at            TEXT    NOT NULL,
                decided_at            TEXT,
                decided_by_profile_id INTEGER               REFERENCES profiles(id) ON DELETE SET NULL,
                created_at            TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE INDEX idx_workspace_ownership_offers_tenant ON workspace_ownership_offers (tenant_id, status);
CREATE INDEX idx_workspace_ownership_offers_to ON workspace_ownership_offers (to_profile_id, status);
CREATE TABLE calendar_booking_services (
                id            INTEGER PRIMARY KEY,
                tenant_id     INTEGER   NOT NULL REFERENCES tenants(id)           ON DELETE CASCADE,
                booking_id    INTEGER   NOT NULL REFERENCES calendar_bookings(id) ON DELETE CASCADE,
                service_id    INTEGER   NOT NULL REFERENCES calendar_services(id) ON DELETE RESTRICT,
                profile_id    INTEGER   NOT NULL REFERENCES profiles(id)          ON DELETE RESTRICT,
                room_id       INTEGER            REFERENCES calendar_rooms(id)    ON DELETE SET NULL,
                position      INTEGER   NOT NULL,
                starts_at     TEXT NOT NULL,
                ends_at       TEXT NOT NULL,
                blocks_from   TEXT NOT NULL,
                blocks_until  TEXT NOT NULL,
                price_minor   BIGINT,
                created_at    TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (tenant_id, booking_id, position)
            );
CREATE INDEX idx_calendar_booking_services_person ON calendar_booking_services(tenant_id, profile_id, blocks_from);
CREATE INDEX idx_calendar_booking_services_room ON calendar_booking_services(tenant_id, room_id, blocks_from);
CREATE TABLE dashboard_layout (
                tenant_id INTEGER NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                profile_id INTEGER NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
                item_key TEXT NOT NULL,
                position INTEGER NULL,
                hidden INTEGER NOT NULL DEFAULT 0,
                size TEXT NULL,
                updated_at TEXT NOT NULL DEFAULT (datetime('now')),
                PRIMARY KEY (tenant_id, profile_id, item_key)
            );
CREATE TABLE workspace_template_runs (
                id                     INTEGER       PRIMARY KEY,
                tenant_id              INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                template_key           TEXT  NOT NULL,
                plugin_name            TEXT NULL,
                version                INTEGER      NOT NULL DEFAULT 1,
                applied_by_profile_id  INTEGER      NULL REFERENCES profiles(id) ON DELETE SET NULL,
                applied_at             TEXT NOT NULL DEFAULT (datetime('now')),
                setup_closed_at        TEXT    NULL,
                offer_closed_at        TEXT    NULL,
                UNIQUE (tenant_id, template_key)
            );
CREATE TABLE workspace_template_items (
                id          INTEGER      PRIMARY KEY,
                tenant_id   INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                run_id      INTEGER     NOT NULL REFERENCES workspace_template_runs(id) ON DELETE CASCADE,
                kind        TEXT NOT NULL,
                item_key    TEXT NOT NULL,
                ref_id      TEXT NOT NULL,
                is_example  INTEGER     NOT NULL DEFAULT 0,
                removed_at  TEXT   NULL,
                created_at  TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE (run_id, kind, item_key)
            );
CREATE INDEX idx_workspace_template_items_tenant ON workspace_template_items (tenant_id, is_example);
CREATE UNIQUE INDEX idx_calendar_events_time_off_ref
                 ON calendar_events(tenant_id, external_ref)
              WHERE kind = 'time_off' AND status = 'confirmed' AND external_ref IS NOT NULL;
CREATE TABLE mcp_call_keys (
                id              INTEGER    NOT NULL PRIMARY KEY,
                tenant_id       INTEGER      NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                principal       TEXT NOT NULL,
                tool            TEXT NOT NULL,
                idempotency_key TEXT NOT NULL,
                arguments_hash  TEXT  NOT NULL,
                status          TEXT  NOT NULL DEFAULT 'running',
                result          TEXT         NULL,
                created_at      TEXT NOT NULL DEFAULT (datetime('now')),
                finished_at     TEXT    NULL,
                UNIQUE (tenant_id, principal, tool, idempotency_key)
            );
CREATE INDEX idx_mcp_call_keys_created ON mcp_call_keys(created_at);
CREATE UNIQUE INDEX uq_agent_proposals_waiting_call
                 ON agent_proposals(tenant_id, agent_principal_id, on_behalf_of_profile_id, tool, arguments_hash)
              WHERE status = 'waiting' AND arguments_hash IS NOT NULL;

