(1353, 1, 'admin', 'convening.meeting.invitations.intro.value', 'What people SAID before the sitting. An acceptance is a prediction; who actually came is recorded separately, below.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(1354, 1, 'admin', 'convening.meeting.minute.card.description', 'Choose an agenda item above, then record what the body concluded about it. A decision can only be minuted once the meeting has been held, and it cannot be edited afterwards — a body that changes its mind takes a new decision at a later sitting.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(1355, 1, 'admin', 'convening.meeting.minute.card.title', 'Minute a decision', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(1356, 1, 'admin', 'convening.meeting.minute.note.value', 'Nothing is minuted until you press Record decision. If the item carries a document and this body is the one its approval route is waiting for, an approval here advances that document and a rejection stops it.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(1357, 1, 'admin', 'convening.meeting.minute.nothingChosen.value', 'No agenda item chosen yet — use "Minute a decision" on a row above.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
