(2875, 1, 'admin', 'routeTemplates.inspector.decisionExcludesDelivery', 'A decision needs somebody holding the item to answer it, so this stage cannot also send without asking.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(2876, 1, 'admin', 'routeTemplates.inspector.delivery', 'Sends without asking', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(2877, 1, 'admin', 'routeTemplates.inspector.deliveryExplained', 'Everybody this stage reaches is sent the document and asked for nothing. Their item closes the moment it is sent, so the flow continues immediately and this stage cannot also be a decision.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(2878, 1, 'admin', 'routeTemplates.inspector.edgeHint', 'Drag from the green handle to draw where an approval goes, and from the red one for a rejection. With no approval edge the flow continues to the next stage; with no rejection edge it stops.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
