(2881, 1, 'admin', 'routeTemplates.inspector.exclusionsHelp', 'People picked in these questions or stage values, such as the supervisor, are not asked here, are not counted towards approval and are not printed among the approvals.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(2882, 1, 'admin', 'routeTemplates.inspector.group', 'User group', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(2883, 1, 'admin', 'routeTemplates.inspector.groupDynamic', 'This is who the group means right now. It is re-resolved every time the stage is reached, so a document routed next month reaches whoever matches then.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(2884, 1, 'admin', 'routeTemplates.inspector.label', 'Label', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
