(3290, 1, 'admin', 'settings.meta.auth.self_registration_enabled.help', 'Let anyone create an account from the public registration page. Off by default — an operator-provisioned instance opens sign-up explicitly.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(3291, 1, 'admin', 'settings.meta.auth.self_registration_enabled.label', 'Public sign-up', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(3292, 1, 'admin', 'settings.meta.auth.sso_enabled.help', 'Master switch for federated sign-in. When off, every configured identity provider is disabled instance-wide.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(3293, 1, 'admin', 'settings.meta.auth.sso_enabled.label', 'Single sign-on (SSO)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
