(7263, 1, 'documents', 'record.qr.scans.who', 'Who', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7264, 1, 'documents', 'record.qr.stranded.body', 'Reference {reference} was retired {when} when a newer code was issued, but this document is not carrying one now.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7265, 1, 'documents', 'record.qr.stranded.bodyPlain', 'Reference {reference} was retired when a newer code was issued, but this document is not carrying one now.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7266, 1, 'documents', 'record.qr.stranded.title', 'No code is in force', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7267, 1, 'documents', 'record.qr.subtitle', 'A printed code lets anyone confirm this document is genuine. It identifies the document; it never grants access to it.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7268, 1, 'documents', 'record.qr.title', 'Verification code', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7269, 1, 'documents', 'record.qr.unconfigured.body', 'A verification code encodes a web address, and nobody has told this installation its own. Until an operator sets APP_URL, a code issued here would lead nowhere.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7270, 1, 'documents', 'record.qr.unconfigured.title', 'This installation has no public address', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7271, 1, 'documents', 'record.qr.whatItDoes', 'Scanning it opens a public page that confirms this document is genuine and names this organisation. The page shows no content, no recipients and nobody’s name — and it grants nothing: somebody who may not read this document is refused exactly as they are today, whether or not they hold the paper.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7272, 1, 'documents', 'record.qr.withdrawDialog.finalBody', 'A code can never be un-withdrawn. Issuing one later creates a different code; it does not bring this one back, and it does not change paper that is already printed.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7273, 1, 'documents', 'record.qr.withdrawDialog.finalTitle', 'This cannot be undone', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7274, 1, 'documents', 'record.qr.withdrawDialog.paper', 'All {versions} issued versions of this document carry this code. Every copy already printed keeps the symbol and stops confirming anything.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7275, 1, 'documents', 'record.qr.withdrawDialog.paperOne', 'The one issued version of this document carries this code. Every copy already printed keeps the symbol and stops confirming anything.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7276, 1, 'documents', 'record.qr.withdrawDialog.reference', 'Reference {reference}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7277, 1, 'documents', 'record.qr.withdrawDialog.scanner', 'Anyone who scans it from now on — a courier, a clerk, somebody holding your letter — is refused a confirmation.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7278, 1, 'documents', 'record.qr.withdrawDialog.scans', '{count} scans of it are already recorded.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7279, 1, 'documents', 'record.qr.withdrawDialog.scansNone', 'No scan of this code has been recorded yet.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7280, 1, 'documents', 'record.qr.withdrawDialog.scansOne', 'One scan of it is already recorded.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7281, 1, 'documents', 'record.qr.withdrawDialog.submit', 'Withdraw the code', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7282, 1, 'documents', 'record.qr.withdrawDialog.title', 'Withdraw the verification code from “{title}”?', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7283, 1, 'documents', 'record.qr.withdrawn.consequence', 'Every copy already printed still carries that symbol, and scanning one no longer confirms anything. A withdrawal cannot be reversed — issuing a code now creates a different one and does not bring this back.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7284, 1, 'documents', 'record.qr.withdrawn.plain', 'Reference {reference} stopped being honoured.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7285, 1, 'documents', 'record.qr.withdrawn.plainBy', 'Reference {reference} stopped being honoured, withdrawn by {who}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7286, 1, 'documents', 'record.qr.withdrawn.title', 'This code was withdrawn', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7287, 1, 'documents', 'record.qr.withdrawn.when', 'Reference {reference} stopped being honoured {when}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7288, 1, 'documents', 'record.qr.withdrawn.whenBy', 'Reference {reference} stopped being honoured {when}, withdrawn by {who}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7289, 1, 'documents', 'record.recipients.closed', '{count} already acted on it. What each of them did is in the trail below.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7290, 1, 'documents', 'record.recipients.in', 'In {unit}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7291, 1, 'documents', 'record.recipients.inVia', 'In {unit}, forwarded by {who}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7292, 1, 'documents', 'record.recipients.readOnly.record', 'This document is not awaiting you. You are reading it as a record rather than as something to act on.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7293, 1, 'documents', 'record.recipients.settled', 'Nobody is holding this document. Everyone it reached has acted on it.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7294, 1, 'documents', 'record.recipients.since', 'In {unit} since {when}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7295, 1, 'documents', 'record.recipients.sinceVia', 'In {unit} since {when}, forwarded by {who}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7296, 1, 'documents', 'record.recipients.you', 'You', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7297, 1, 'documents', 'record.recipients.youBody', 'It is on your list until you act on it. Forwarding, acknowledging and returning are done from your inbox, which is the one place those actions live.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7298, 1, 'documents', 'record.recipients.youTitle', 'This document is awaiting you', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
