(7316, 1, 'documents', 'record.trail.action.issued', 'Issued', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7317, 1, 'documents', 'record.trail.action.noted', 'Note added', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7318, 1, 'documents', 'record.trail.action.resubmitted', 'Resubmitted by the author', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
