(7320, 1, 'documents', 'record.trail.action.sentBack', 'Sent back to the author for changes', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7321, 1, 'documents', 'record.trail.action.signed', 'Signed electronically', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7322, 1, 'documents', 'record.trail.action.stamped', 'Stamped', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7323, 1, 'documents', 'record.trail.action.withdrawal', 'Withdrew the document, closing what was waiting on this route', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7324, 1, 'documents', 'record.trail.by', '{who} — {when}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7325, 1, 'documents', 'record.trail.loading', 'Reading the trail…', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7326, 1, 'documents', 'record.trail.none', 'Nothing has been recorded against this document. A trail begins when it is sent into a route, and every step it takes is appended here.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7327, 1, 'documents', 'record.trail.noneWithdrawn', 'It was withdrawn without ever being sent into a route.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7328, 1, 'documents', 'record.trail.pager', 'Trail pages', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7329, 1, 'documents', 'record.trail.pastEnd', 'There are no entries on this page of the trail.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7330, 1, 'documents', 'record.trail.readOnly.record', 'This document has not been put into circulation, so nothing has happened to it yet.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7331, 1, 'documents', 'record.trail.subtitle', 'Append-only. An entry is never edited or removed — a correction is a new entry.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7332, 1, 'documents', 'record.trail.title', 'What has happened to it', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7333, 1, 'documents', 'record.unit.byId', 'Unit #{id}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7334, 1, 'documents', 'record.unit.none', 'No unit', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7335, 1, 'documents', 'record.withdraw.action', 'Withdraw this document', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7336, 1, 'documents', 'record.withdraw.cancel', 'Keep it', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7337, 1, 'documents', 'record.withdraw.confirm', 'Withdraw document', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7338, 1, 'documents', 'record.withdraw.consequence', 'Its printed codes stop confirming it, anyone waiting on it is no longer asked, and it cannot be sent on or corrected. The record and its history are kept. This cannot be undone.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7339, 1, 'documents', 'record.withdraw.done', 'The document was withdrawn', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7340, 1, 'documents', 'record.withdraw.error', 'The document could not be withdrawn', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7341, 1, 'documents', 'record.withdraw.title', 'Withdraw {title}?', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7342, 1, 'documents', 'record.withdrawn.body', '{who} withdrew it on {when}. The record is kept, but its codes no longer confirm anything and nothing further can happen on its routes.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7343, 1, 'documents', 'record.withdrawn.bodyNoDate', '{who} withdrew it. The record is kept, but its codes no longer confirm anything and nothing further can happen on its routes.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7344, 1, 'documents', 'record.withdrawn.title', 'This document was withdrawn', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7345, 1, 'documents', 'routing.act.acknowledge', 'Acknowledge', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7346, 1, 'documents', 'routing.act.approve', 'Approve', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7347, 1, 'documents', 'routing.act.decision.approved.ends', 'Approved. This step is approved, and the route names nowhere for it to go next — so the document goes no further along this chain.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7348, 1, 'documents', 'routing.act.decision.approved.moved', 'Approved. The document has moved on and reached {people}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7349, 1, 'documents', 'routing.act.decision.badge', 'Decision', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7350, 1, 'documents', 'routing.act.decision.heading', 'Your decision on this route', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7351, 1, 'documents', 'routing.act.decision.item', 'Step {position} is a decision step, and it is asking you to approve or reject. Where the document goes next follows from your verdict rather than from a destination you choose.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7352, 1, 'documents', 'routing.act.decision.pending.approved', 'Your approval is recorded. This step is not approved yet — it is still waiting on the other people it was put to.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7353, 1, 'documents', 'routing.act.decision.pending.rejected', 'Your rejection is recorded. This step is not settled yet — under its approval rule the people who have not answered can still carry it.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7354, 1, 'documents', 'routing.act.decision.rejected.ends', 'Rejected. This step can no longer be approved, and the route draws no path for a rejection — so the document goes no further along this chain. A rejection never falls through to where an approval would have sent it.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7355, 1, 'documents', 'routing.act.decision.rejected.moved', 'Rejected. The document went where the route sends a rejection and reached {people}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7356, 1, 'documents', 'routing.act.delivered', 'This route sent you the document. You were not asked to act on it, so it is not waiting on you.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7357, 1, 'documents', 'routing.act.delivered.heading', 'This route sent you the document', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7358, 1, 'documents', 'routing.act.deliveredAtStep', 'Step {position} sent you the document. You were not asked to act on it, so it is not waiting on you.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7359, 1, 'documents', 'routing.act.denied.decisionStep', 'Step {position} is a decision step: it is answered with a verdict, and where the document goes next follows from that verdict. Forwarding would let you choose the destination the step exists to decide.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7360, 1, 'documents', 'routing.act.denied.delivered', 'This route sent you the document rather than asking you for anything, so there is nothing here to answer. You can still add a note.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7361, 1, 'documents', 'routing.act.denied.firstStep', 'This item came from the first step of the route, so there is no earlier recipient to return it to. Acknowledge it, or add a note explaining the problem.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7362, 1, 'documents', 'routing.act.denied.lastStep', 'This is the last step of the route, so there is nothing to forward to. Acknowledge it instead.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7363, 1, 'documents', 'routing.act.denied.noOpenItem', 'You have no open item on this route. An item you have already acted on cannot be acted on again — add a note instead, which appends to the trail without changing what happened.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7364, 1, 'documents', 'routing.act.error', 'The action could not be recorded.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7365, 1, 'documents', 'routing.act.error.network', 'The action could not be sent.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7366, 1, 'documents', 'routing.act.forward', 'Forward', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7367, 1, 'documents', 'routing.act.forwarded.ok', 'Recorded. The next step reached {people}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7368, 1, 'documents', 'routing.act.heading', 'Your action on this route', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7369, 1, 'documents', 'routing.act.item', 'You have an open item at step {position}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7370, 1, 'documents', 'routing.act.itemUnknownStep', 'You have an open item on this route.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7371, 1, 'documents', 'routing.act.noItem', 'Nothing on this route is awaiting you. You can still add a note — the trail has no edit path, so a correction is appended beside what it corrects.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7372, 1, 'documents', 'routing.act.note.count', '{used} of {max} characters', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7373, 1, 'documents', 'routing.act.note.decisionLabel', 'Reason (optional, appended to the trail beside your verdict)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7374, 1, 'documents', 'routing.act.note.label', 'Note (optional, appended to the trail)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7375, 1, 'documents', 'routing.act.note.placeholder', 'What should the record say?', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7376, 1, 'documents', 'routing.act.noted', 'Add note', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7377, 1, 'documents', 'routing.act.noted.needsText', 'A note needs some text to append.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7378, 1, 'documents', 'routing.act.noted.ok', 'Note added to the trail.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7379, 1, 'documents', 'routing.act.quorum.all', 'Every one of them must approve. One rejection settles it, because unanimity is impossible after that.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7380, 1, 'documents', 'routing.act.quorum.any', 'One approval from any of them carries it, so yours may settle it on its own. A rejection decides nothing while anybody is still able to approve.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7381, 1, 'documents', 'routing.act.quorum.cohort', 'This step was put to {count} people at once.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7382, 1, 'documents', 'routing.act.quorum.first', 'The first of them to answer decides, approve or reject. Once someone has answered, nothing more is needed from the others.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7383, 1, 'documents', 'routing.act.quorum.inherited', 'That is this tenant’s rule for approval steps; this step does not override it.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7384, 1, 'documents', 'routing.act.quorum.majority', 'It is approved when more than half of them approve, and refused as soon as a majority in favour has become impossible.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7385, 1, 'documents', 'routing.act.quorum.onStep', 'This step names that rule itself.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7386, 1, 'documents', 'routing.act.reject', 'Reject', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7387, 1, 'documents', 'routing.act.return', 'Return to sender', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7388, 1, 'documents', 'routing.act.values.choose', 'Choose one', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7389, 1, 'documents', 'routing.act.values.decisionTitle', 'Fill in before you approve', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(7390, 1, 'documents', 'routing.act.values.optional', '(optional)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
