(8479, 1, 'onboarding', 'denied.dashboard', 'Go to dashboard', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8480, 1, 'onboarding', 'denied.description', 'First-run setup configures instance-wide defaults, so it can only be run by an operator of the system tenant. Sign in with the operator account to continue.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8481, 1, 'onboarding', 'denied.title', 'Setup is operator-only', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8482, 1, 'onboarding', 'error.finalize', 'Could not finalize first-run setup', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8483, 1, 'onboarding', 'error.finish', 'Could not finalize setup', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8484, 1, 'onboarding', 'error.load', 'Failed to load instance settings', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8485, 1, 'onboarding', 'error.save', 'Could not save your settings', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8486, 1, 'onboarding', 'finish.defaults', 'Setup complete. You can fine-tune everything in Settings.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8487, 1, 'onboarding', 'finish.saved', 'Setup complete. Your instance is ready.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8488, 1, 'onboarding', 'guide.email.connection.from', 'From address / name is what recipients see the mail come from.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8489, 1, 'onboarding', 'guide.email.connection.heading', 'SMTP connection', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8490, 1, 'onboarding', 'guide.email.connection.host', 'Host — your provider’s SMTP server, e.g. mail.yourdomain.com (cPanel), smtp.gmail.com (Google), or email-smtp.<region>.amazonaws.com (Amazon SES).', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8491, 1, 'onboarding', 'guide.email.connection.port', 'Port + Encryption go together: 587 → TLS (STARTTLS) or 465 → SSL. Use a hostname the TLS certificate actually covers.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8492, 1, 'onboarding', 'guide.email.connection.username', 'Username is usually the full email address of the mailbox you send from.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8493, 1, 'onboarding', 'guide.email.credentials.cpanel', 'cPanel: Email Accounts → Connect Devices shows the host, ports and username.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8494, 1, 'onboarding', 'guide.email.credentials.google', 'Google Workspace / Gmail: create an App Password (with 2-Step Verification on) and use it as the SMTP password.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8495, 1, 'onboarding', 'guide.email.credentials.heading', 'Where to find your credentials', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8496, 1, 'onboarding', 'guide.email.credentials.ses', 'Amazon SES: create SMTP credentials in the SES console (these are distinct from your AWS keys).', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8497, 1, 'onboarding', 'guide.email.link', 'Open Email settings (password + test send)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8498, 1, 'onboarding', 'guide.email.password.body', 'The SMTP password is stored encrypted and set on the Email settings page, which also has a “send test email” button to verify the connection end-to-end.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8499, 1, 'onboarding', 'guide.email.password.heading', 'Password & test send', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8500, 1, 'onboarding', 'guide.email.summary', 'How to connect an SMTP mailbox — and where to find the details.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8501, 1, 'onboarding', 'guide.email.transport.heading', 'Transport', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8502, 1, 'onboarding', 'guide.email.transport.options', '“None” disables email entirely. “Log” writes messages to the app log (handy while testing). “SMTP” sends real email through your mail provider.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8503, 1, 'onboarding', 'guide.hide', 'Hide', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8504, 1, 'onboarding', 'guide.show', 'Show', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8505, 1, 'onboarding', 'guide.signin.link', 'Open SSO settings', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8506, 1, 'onboarding', 'guide.signin.masterSwitch', 'This is the instance-wide master switch for federated sign-in. When off, every configured identity provider is disabled.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8507, 1, 'onboarding', 'guide.signin.providers', 'Individual providers (e.g. Google) are added on the SSO settings page: create an OAuth client in your provider, set the redirect URI it gives you, then paste the client ID/secret there.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8508, 1, 'onboarding', 'guide.signin.summary', 'The SSO master switch; add individual providers on the SSO page.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8509, 1, 'onboarding', 'guide.signup.approval', 'Require admin approval holds each new account as “pending” until an administrator approves it. Leave it on when sign-up is open so nobody gets access unreviewed.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8510, 1, 'onboarding', 'guide.signup.publicSignup', 'Public sign-up lets anyone create an account from the sign-in screen. It is OFF by default — an operator-provisioned instance opens it deliberately.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8511, 1, 'onboarding', 'guide.signup.summary', 'What open sign-up and approval mean for your instance.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8512, 1, 'onboarding', 'guide.storage.driver.heading', 'Driver', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8513, 1, 'onboarding', 'guide.storage.driver.local', '“local” stores uploaded files on the server’s disk — fine for a single-node deployment.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8514, 1, 'onboarding', 'guide.storage.driver.s3', 'For durability or multi-node, use an S3-compatible object store (AWS S3, MinIO, Cloudflare R2, Backblaze B2, …) by setting the driver to “s3”.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8515, 1, 'onboarding', 'guide.storage.s3.accessKey', 'Access key — the public key ID. The matching SECRET key is supplied via the deployment environment and is never stored here.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8516, 1, 'onboarding', 'guide.storage.s3.endpoint', 'Endpoint — the object store’s base URL (e.g. https://s3.amazonaws.com, or your MinIO/R2 endpoint).', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8517, 1, 'onboarding', 'guide.storage.s3.heading', 'S3 settings', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8518, 1, 'onboarding', 'guide.storage.s3.pathStyle', 'Path-style addressing — turn on for most self-hosted gateways (MinIO); AWS uses virtual-hosted style.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8519, 1, 'onboarding', 'guide.storage.s3.publicBaseUrl', 'Public base URL — set only if assets are served from a different (CDN) host than the endpoint.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8520, 1, 'onboarding', 'guide.storage.s3.region', 'Region / Bucket — as created in your provider’s console.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8521, 1, 'onboarding', 'guide.storage.summary', 'Keep files on local disk, or point at an S3-compatible object store.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(8522, 1, 'onboarding', 'guide.toggle', 'Need help?', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
