(9255, 2, 'admin', 'aiPrincipals.connect.preflight.tenantOff', 'يستطيع مسؤول مؤسستك تشغيل نقطة MCP من الإعدادات ثم التكاملات. وإن كانت مفعّلة فخطة هذه المؤسسة لا تشمل تطبيقات الذكاء الاصطناعي.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(9256, 2, 'admin', 'aiPrincipals.connect.preflight.tenantOffTitle', 'تطبيقات الذكاء الاصطناعي معطّلة لهذه المؤسسة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(9257, 2, 'admin', 'aiPrincipals.connect.preview.count', 'الإجراءات التي سيتمكن التطبيق من استخدامها: {count}. على سبيل المثال:', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(9258, 2, 'admin', 'aiPrincipals.connect.preview.none', 'بهذا الاختيار لن يتمكن التطبيق من فعل أي شيء. اختر المزيد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
