(11867, 2, 'admin', 'settings.email.oauth.state.clientRejected', 'لا يُرسل البريد الآن. رفض المزوّد معرّف العميل أو سر العميل. تحقّق منهما، فأسرار العميل قد تنتهي صلاحيتها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(11868, 2, 'admin', 'settings.email.oauth.state.connected', 'متصل. أُرسلت آخر رسالة باستخدام هذا الحساب.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(11869, 2, 'admin', 'settings.email.oauth.state.credentialsUnreadable', 'لا يُرسل البريد الآن. لم تعد قراءة بيانات الاعتماد المحفوظة ممكنة، وغالباً لأن مفتاح التشفير تغيّر. أدخلها مرة أخرى.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(11870, 2, 'admin', 'settings.email.oauth.state.hostNotAllowed', 'لا يُرسل البريد الآن. مضيف SMTP ليس من خوادم بريد هذا المزوّد، لذلك لا يُرسل إليه رمز تسجيل الدخول.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(11871, 2, 'admin', 'settings.email.oauth.state.insecure', 'لا يُرسل البريد الآن. يحتاج OAuth إلى اتصال مشفَّر. اضبط التشفير على TLS أو SSL.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(11872, 2, 'admin', 'settings.email.oauth.state.needsReconnect', 'لا يُرسل البريد الآن. يقول المزوّد إن رمز التحديث أُلغي أو انتهت صلاحيته. احصل على رمز تحديث جديد واحفظه هنا.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(11873, 2, 'admin', 'settings.email.oauth.state.notConnected', 'غير متصل بعد. أدخل معرّف العميل وسر العميل ورمز التحديث.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(11874, 2, 'admin', 'settings.email.oauth.state.notYetUsed', 'جاهز للتجربة. أرسل رسالة اختبار أدناه للتأكد من أن الاتصال يعمل.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(11875, 2, 'admin', 'settings.email.oauth.state.smtpRejected', 'لا يُرسل البريد الآن. رفض خادم البريد تسجيل الدخول. تأكد من أن اسم مستخدم SMTP هو صندوق البريد الذي منح الإذن، وأن تسجيل الدخول عبر SMTP مفعّل له.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(11876, 2, 'admin', 'settings.email.oauth.state.tokenServiceUnavailable', 'تعذّر الوصول إلى المزوّد قبل قليل. سيعيد البريد المحاولة من تلقاء نفسه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
