(11997, 2, 'admin', 'settings.featureFlags.passwordResetApproval.belowMinimum', 'مساحة عمل النظام نفسها دون ذلك حالياً: عدد الحسابات القادرة على الاعتماد هنا {count}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(11998, 2, 'admin', 'settings.featureFlags.passwordResetApproval.warning', 'ينطبق هذا على كل مساحة عمل. فمساحة العمل التي لا يستطيع اعتماد إعادة تعيين كلمة المرور فيها سوى حساب واحد لا تستطيع اعتماد إعادة تعيين ذلك الحساب نفسه، لذا امنح كل مساحة عمل حسابين على الأقل يحملان صلاحية اعتماد إعادة تعيين كلمة المرور قبل الاعتماد على هذا. ويستطيع مشغّل من مساحة عمل النظام اعتماد إعادة تعيين في أي مساحة عمل، وهو المخرج إن تعثّرت إحداها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
