(12054, 2, 'admin', 'settings.messages.webchat.greetingHint', 'مرحبًا! كيف يمكننا مساعدتك؟', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12055, 2, 'admin', 'settings.messages.webchat.title', 'الدردشة على الموقع', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12056, 2, 'admin', 'settings.messages.webchat.toggle', 'تشغيل الدردشة على الموقع', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12057, 2, 'admin', 'settings.meta.app.installable.help', 'أتِح للناس إضافة هذا الموقع إلى هواتفهم أو حواسيبهم كتطبيق يُفتح في نافذته الخاصة ويعرض صفحة خاصة به عند انقطاع الاتصال. والإيقاف يُزيل هذا الخيار ويُلغي دعم التطبيق دون اتصال من المتصفحات عند فتحها أي صفحة في المرة التالية. وإلى أن يُحفظ هذا الإعداد هنا، يقرّر إعداد PWA_ENABLED في الخادم.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12058, 2, 'admin', 'settings.meta.app.installable.label', 'التثبيت كتطبيق', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12059, 2, 'admin', 'settings.meta.auth.password_sign_in.help', 'عند الإيقاف يسجّل الناس الدخول وينشئون حساباتهم عبر مزوّد الهوية فقط، ويتوقف تسجيل الدخول بكلمة المرور واستعادتها وإعداد التحقق بخطوتين. يمكن إعادة تشغيله من الخادم بالأمر whity-cli auth password-sign-in on.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12060, 2, 'admin', 'settings.meta.auth.password_sign_in.label', 'تسجيل الدخول بكلمة المرور', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12061, 2, 'admin', 'settings.meta.auth.registration_approval_required.help', 'عندما يكون التسجيل مفتوحاً، أبقِ كل حساب جديد معلّقاً حتى يوافق عليه أحد المسؤولين.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12062, 2, 'admin', 'settings.meta.auth.registration_approval_required.label', 'اشتراط موافقة المسؤول', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12063, 2, 'admin', 'settings.meta.auth.self_2fa_recovery_enabled.help', 'يتيح لمن فقدوا جهاز التحقق بخطوتين أن يطلبوا العودة بأنفسهم. وتمرّ الطلبات عبر بوابة الاعتماد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12064, 2, 'admin', 'settings.meta.auth.self_2fa_recovery_enabled.label', 'استعادة الدخول الذاتية عند فقدان جهاز التحقق بخطوتين', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12065, 2, 'admin', 'settings.meta.auth.self_registration_enabled.help', 'أتِح لأي شخص إنشاء حساب من صفحة التسجيل العامة. وهو معطّل افتراضياً — فالنظام الذي يزوّده المشغّل يفتح التسجيل صراحةً.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12066, 2, 'admin', 'settings.meta.auth.self_registration_enabled.label', 'التسجيل العام', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12067, 2, 'admin', 'settings.meta.auth.sso_enabled.help', 'المفتاح الرئيسي للدخول الموحّد. وعند إيقافه، يُعطَّل كل مزوّد هوية مضبوط على مستوى النظام كله.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12068, 2, 'admin', 'settings.meta.auth.sso_enabled.label', 'الدخول الموحّد (SSO)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(12069, 2, 'admin', 'settings.meta.auth.sso_self_provision_workspace.help', 'يمنح من يسجّل الدخول عبر مزوّد هوية المشغّل ولا ينتمي إلى أي مساحة عمل مساحة عمل جديدة خاصة به.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
