(15801, 2, 'documents', 'organizer.chips.label', 'المجموعات', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15802, 2, 'documents', 'organizer.collection.builtIn', '«المميّزة بنجمة» مجموعة مدمجة. عنصر النجمة يشير إليها بالاسم، لذلك لا يمكن إعادة تسميتها أو حذفها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15803, 2, 'documents', 'organizer.collection.confirmDelete', 'حذف', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15804, 2, 'documents', 'organizer.collection.create', 'إنشاء', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15805, 2, 'documents', 'organizer.collection.delete', 'حذف هذه المجموعة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15806, 2, 'documents', 'organizer.collection.deleteHelp', 'لن تتأثّر المستندات التي بداخلها — فالمجموعة تحتفظ بمؤشّرات لا بملفات. لن يُحذف سوى تصنيفك الخاص.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15807, 2, 'documents', 'organizer.collection.deleteTitle', 'حذف هذه المجموعة؟', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15808, 2, 'documents', 'organizer.collection.manage', 'هذه المجموعة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15809, 2, 'documents', 'organizer.collection.name', 'الاسم', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15810, 2, 'documents', 'organizer.collection.new', 'مجموعة جديدة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15811, 2, 'documents', 'organizer.collection.newHelp', 'المجموعة ملكك وحدك. وضع مستند فيها لا يقول شيئاً عن مكان حفظه، ولا يستطيع أحد غيرك رؤية مجموعاتك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15812, 2, 'documents', 'organizer.collection.newTitle', 'مجموعة جديدة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15813, 2, 'documents', 'organizer.collection.rename', 'إعادة تسمية…', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15814, 2, 'documents', 'organizer.collection.renameHelp', 'الاسم وحده هو ما يتغيّر. المستندات داخلها لا تُمَس، ولم يرَ أحد غيرك الاسم القديم قط.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15815, 2, 'documents', 'organizer.collection.renameTitle', 'إعادة تسمية هذه المجموعة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15816, 2, 'documents', 'organizer.collection.saveName', 'إعادة التسمية', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15817, 2, 'documents', 'organizer.description', 'كل مجلد هنا بحث محفوظ في مستنداتك. المجموعات ملكك، وإضافة مستند إلى إحداها لا تنقله.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15818, 2, 'documents', 'organizer.done', 'تم', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15819, 2, 'documents', 'organizer.empty.collectionHelp', 'استخدم قائمة المستند لإضافته إلى هذه المجموعة. أنت وحدك من يرى مجموعاتك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15820, 2, 'documents', 'organizer.empty.collectionTitle', 'لم يُصنَّف شيء هنا بعد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15821, 2, 'documents', 'organizer.empty.filedButUnreadableHelp', 'المجموعة تحتفظ بمؤشّرات، وما يحق لك قراءته يُتحقَّق منه في كل زيارة. لم يُحذف شيء من مجموعتك — بل لم تعد تملك صلاحية قراءته. راجع مالك المستندات إن كان ذلك غير متوقَّع.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15822, 2, 'documents', 'organizer.empty.filedButUnreadableTitle', 'كل ما صنّفته هنا لم يعد ظاهرًا لك', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15823, 2, 'documents', 'organizer.empty.help', 'هذا المجلد استعلام عمّا تسجّله المستندات. لم يطابقه شيء — ولا يوجد مستند مخفيّ عنه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15824, 2, 'documents', 'organizer.empty.pastEndAction', 'الانتقال إلى الصفحة الأولى', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15825, 2, 'documents', 'organizer.empty.pastEndHelp', 'المجلد يحتوي مستندات، لكن عددها أقل مما كان عند فتح هذه الصفحة. عُد إلى الصفحة الأولى.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15826, 2, 'documents', 'organizer.empty.pastEndTitle', 'هذه الصفحة تتجاوز نهاية المجلد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15827, 2, 'documents', 'organizer.empty.searchHelp', 'البحث يشمل عناوين المستندات فقط. امسحه لترى كل ما يحتويه المجلد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15828, 2, 'documents', 'organizer.empty.searchTitle', 'لا شيء في هذا المجلد يطابق بحثك', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(15829, 2, 'documents', 'organizer.empty.starredHelp', 'استخدم النجمة بجانب المستند للاحتفاظ به هنا. ولا يراه سواك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
