(16001, 2, 'documents', 'record.qr.issuedBy', 'صدر {when} بواسطة {who}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16002, 2, 'documents', 'record.qr.issuedByOnly', 'صدر بواسطة {who}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16003, 2, 'documents', 'record.qr.loading', 'جارٍ قراءة رمز التحقّق…', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16004, 2, 'documents', 'record.qr.mintDialog.printBody', 'إصدار الرمز لا يعيد توليد هذا المستند. فالرمز الجديد يظهر على النسخ التي تصدر من الآن، ولا يحمله شيء ممّا هو متداوَل حتى تُصدَر نسخة مصحّحة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16005, 2, 'documents', 'record.qr.mintDialog.printTitle', 'الأوراق المطبوعة سابقاً لا تتغيّر', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16006, 2, 'documents', 'record.qr.mintDialog.retiresBody', 'يُسحَب المرجع {reference} فور نجاح هذه العملية. وكل نسخة مطبوعة سابقاً تحمله، ولن يؤكّد مسحها ضوئياً هذا المستند بعد الآن.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16007, 2, 'documents', 'record.qr.mintDialog.retiresTitle', 'الرمز الحالي يتوقّف عن الاعتماد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16008, 2, 'documents', 'record.qr.mintDialog.submitFirst', 'إصدار الرمز', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16009, 2, 'documents', 'record.qr.mintDialog.submitRotate', 'إصدار الرمز الجديد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16010, 2, 'documents', 'record.qr.mintDialog.subtitle', 'الرمز يعرّف هذا المستند ليتمكّن أي شخص من تأكيد صحّته. وهو لا يمنح صلاحية الاطّلاع عليه قط.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16011, 2, 'documents', 'record.qr.mintDialog.titleFirst', 'إصدار رمز تحقّق لـ ”{title}“؟', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16012, 2, 'documents', 'record.qr.mintDialog.titleRotate', 'إصدار رمز تحقّق جديد لـ ”{title}“؟', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16013, 2, 'documents', 'record.qr.noSymbol', 'لا تُعرَض العلامة ولا عنوانها: فهذا التثبيت لم يُخبَر بعنوانه العام، ولذلك لا يستطيع أن يقول ما الذي يحمله الرمز المطبوع.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16014, 2, 'documents', 'record.qr.none', 'لا يحمل هذا المستند رمز تحقّق. وإصدار رمز يمنحه علامة يستطيع أي شخص مسحها ضوئياً لتأكيد صحّته — تظهر على النسخ التي تصدر من الآن، والنسخ المطبوعة سابقاً تبقى كما هي.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16015, 2, 'documents', 'record.qr.outcome.refused', 'لم يُؤكَّد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16016, 2, 'documents', 'record.qr.outcome.verified', 'مؤكَّد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16017, 2, 'documents', 'record.qr.readOnly.permission', 'يمكنك الاطّلاع على رمز التحقّق الخاص بهذا المستند وعلى عدد مرات مسحه. أما إصدار رمز جديد أو سحبه فيتطلّب صلاحية لا يملكها حسابك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16018, 2, 'documents', 'record.qr.readOnly.record', 'لا يمكن إصدار رمز تحقّق لهذا المستند في الوضع الحالي. والسبب مذكور أدناه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16019, 2, 'documents', 'record.qr.retired.more', 'يُعرَض أحدث {shown} من أصل {total}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16020, 2, 'documents', 'record.qr.retired.other', 'سُحِب {when} ({reason})', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16021, 2, 'documents', 'record.qr.retired.otherPlain', 'سُحِب ({reason})', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16022, 2, 'documents', 'record.qr.retired.superseded', 'استُبدل برمز أحدث {when}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16023, 2, 'documents', 'record.qr.retired.supersededPlain', 'استُبدل برمز أحدث', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16024, 2, 'documents', 'record.qr.retired.title', 'رموز لم يعد هذا المستند يعتمدها', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16025, 2, 'documents', 'record.qr.retired.why', 'تُحفَظ ليتمكّن من يحمل نسخة مطبوعة أقدم من معرفة الرمز الذي تحمله ومتى توقّف اعتماده.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16026, 2, 'documents', 'record.qr.retired.withdrawn', 'سُحِب {when}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16027, 2, 'documents', 'record.qr.retired.withdrawnPlain', 'سُحِب', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16028, 2, 'documents', 'record.qr.scans.member', 'شخص مسجّل الدخول', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16029, 2, 'documents', 'record.qr.scans.more', 'يُعرَض أحدث {shown} من أصل {total}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16030, 2, 'documents', 'record.qr.scans.none', 'لم يُمسَح هذا المستند ضوئياً بعد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16031, 2, 'documents', 'record.qr.scans.privacy', 'يسجّل المسح الفعل لا الزائر. وفي المسح العام لا يُخزَّن شيء عن الماسح — لا عنوان ولا جهاز ولا موقع — لأنه لا يوجد حقل يمكن أن يحفظ ذلك. وتُحتسب عمليات المسح المتكرّرة للرمز نفسه خلال دقيقة واحدة مرّةً واحدة، فهذا سجلّ لعمليات المسح لا لمرات فتح الصفحة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16032, 2, 'documents', 'record.qr.scans.public', 'أحد أفراد الجمهور', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16033, 2, 'documents', 'record.qr.scans.refusedNote', '”لم يُؤكَّد“ تعني أن الرمز كان قد سُحِب أو استُبدل وقت مسحه، فلم تؤكّد الصفحة العامة المستند.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16034, 2, 'documents', 'record.qr.scans.result', 'النتيجة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16035, 2, 'documents', 'record.qr.scans.total', 'عدد عمليات المسح الضوئي: {count}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16036, 2, 'documents', 'record.qr.scans.totalOne', 'مُسِح ضوئياً مرّة واحدة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16037, 2, 'documents', 'record.qr.scans.when', 'التاريخ', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16038, 2, 'documents', 'record.qr.scans.who', 'من قام بالمسح', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16039, 2, 'documents', 'record.qr.stranded.body', 'سُحِب المرجع {reference} {when} عند إصدار رمز أحدث، غير أن هذا المستند لا يحمل رمزاً الآن.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16040, 2, 'documents', 'record.qr.stranded.bodyPlain', 'سُحِب المرجع {reference} عند إصدار رمز أحدث، غير أن هذا المستند لا يحمل رمزاً الآن.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16041, 2, 'documents', 'record.qr.stranded.title', 'لا يوجد رمز ساري المفعول', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16042, 2, 'documents', 'record.qr.subtitle', 'الرمز المطبوع يتيح لأي شخص تأكيد أن هذا المستند صحيح. وهو يعرّف المستند، ولا يمنح صلاحية الاطّلاع عليه قط.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16043, 2, 'documents', 'record.qr.title', 'رمز التحقّق', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16044, 2, 'documents', 'record.qr.unconfigured.body', 'رمز التحقّق يشفّر عنوان ويب، ولم يُخبَر هذا التثبيت بعنوانه الخاص. وإلى أن يضبط المشغّل قيمة APP_URL، فإن أي رمز يصدر هنا لن يقود إلى شيء.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16045, 2, 'documents', 'record.qr.unconfigured.title', 'لا يملك هذا التثبيت عنواناً عاماً', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16046, 2, 'documents', 'record.qr.whatItDoes', 'يفتح مسحه ضوئياً صفحة عامة تؤكّد أن هذا المستند صحيح وتذكر اسم هذه المؤسسة. ولا تعرض الصفحة أي محتوى ولا أي مستلِمين ولا اسم أي شخص — وهي لا تمنح شيئاً: فمن لا يحقّ له قراءة هذا المستند يُرفَض تماماً كما يُرفَض اليوم، سواء حمل الورقة أم لم يحملها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16047, 2, 'documents', 'record.qr.withdrawDialog.finalBody', 'لا يمكن التراجع عن سحب رمز أبداً. وإصدار رمز لاحقاً ينشئ رمزاً مختلفاً؛ فهو لا يعيد هذا الرمز، ولا يغيّر الأوراق المطبوعة سابقاً.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16048, 2, 'documents', 'record.qr.withdrawDialog.finalTitle', 'لا يمكن التراجع عن هذا', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16049, 2, 'documents', 'record.qr.withdrawDialog.paper', 'جميع النسخ الصادرة من هذا المستند، وعددها {versions}، تحمل هذا الرمز. وكل نسخة مطبوعة سابقاً تحتفظ بالعلامة وتتوقّف عن تأكيد أي شيء.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16050, 2, 'documents', 'record.qr.withdrawDialog.paperOne', 'النسخة الوحيدة الصادرة من هذا المستند تحمل هذا الرمز. وكل نسخة مطبوعة سابقاً تحتفظ بالعلامة وتتوقّف عن تأكيد أي شيء.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16051, 2, 'documents', 'record.qr.withdrawDialog.reference', 'المرجع {reference}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16052, 2, 'documents', 'record.qr.withdrawDialog.scanner', 'كل من يمسحه ضوئياً من الآن فصاعداً — ساعي بريد، أو موظّف، أو شخص يحمل رسالتك — يُرفَض منحه تأكيداً.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16053, 2, 'documents', 'record.qr.withdrawDialog.scans', 'عدد عمليات المسح المسجَّلة له حتى الآن: {count}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16054, 2, 'documents', 'record.qr.withdrawDialog.scansNone', 'لم تُسجَّل أي عملية مسح لهذا الرمز بعد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16055, 2, 'documents', 'record.qr.withdrawDialog.scansOne', 'سُجِّلت له عملية مسح واحدة حتى الآن.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16056, 2, 'documents', 'record.qr.withdrawDialog.submit', 'سحب الرمز', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16057, 2, 'documents', 'record.qr.withdrawDialog.title', 'سحب رمز التحقّق من ”{title}“؟', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16058, 2, 'documents', 'record.qr.withdrawn.consequence', 'كل نسخة مطبوعة سابقاً ما زالت تحمل تلك العلامة، ولم يعد مسحها ضوئياً يؤكّد شيئاً. ولا يمكن التراجع عن السحب — فإصدار رمز الآن ينشئ رمزاً مختلفاً ولا يعيد هذا الرمز.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16059, 2, 'documents', 'record.qr.withdrawn.plain', 'توقّف اعتماد المرجع {reference}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16060, 2, 'documents', 'record.qr.withdrawn.plainBy', 'توقّف اعتماد المرجع {reference}، وقد سحبه {who}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16061, 2, 'documents', 'record.qr.withdrawn.title', 'سُحِب هذا الرمز', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16062, 2, 'documents', 'record.qr.withdrawn.when', 'توقّف اعتماد المرجع {reference} {when}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16063, 2, 'documents', 'record.qr.withdrawn.whenBy', 'توقّف اعتماد المرجع {reference} {when}، وقد سحبه {who}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16064, 2, 'documents', 'record.recipients.closed', '{count} تصرّفوا فيه سابقاً. وما فعله كل منهم مدوَّن في سجل الحركة أدناه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
