(16067, 2, 'documents', 'record.recipients.readOnly.record', 'هذا المستند ليس في انتظارك. أنت تقرؤه بوصفه سجلاً لا بوصفه عملاً تتصرّف فيه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16068, 2, 'documents', 'record.recipients.settled', 'لا أحد يحتفظ بهذا المستند. فقد تصرّف فيه كل من وصله.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
