(16104, 2, 'documents', 'record.trail.pastEnd', 'لا توجد مدخلات في هذه الصفحة من سجل الحركة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16105, 2, 'documents', 'record.trail.readOnly.record', 'لم يوضَع هذا المستند في التداول، فلم يحدث له شيء بعد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16106, 2, 'documents', 'record.trail.subtitle', 'الإلحاق فقط. لا يُعدَّل أي مدخل ولا يُحذف — فالتصحيح مدخل جديد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16107, 2, 'documents', 'record.trail.title', 'ما جرى له', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16108, 2, 'documents', 'record.unit.byId', 'الوحدة رقم {id}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16109, 2, 'documents', 'record.unit.none', 'بلا وحدة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16110, 2, 'documents', 'record.withdraw.action', 'سحب هذا المستند', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16111, 2, 'documents', 'record.withdraw.cancel', 'إبقاؤه', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16112, 2, 'documents', 'record.withdraw.confirm', 'سحب المستند', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16113, 2, 'documents', 'record.withdraw.consequence', 'لن تؤكّده بعد الآن رموزه المطبوعة، ولن يُطلب شيء ممن ينتظرونه، ولا يمكن إرساله أو تصحيحه. يبقى السجل وتاريخه محفوظين. ولا يمكن التراجع عن هذا.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16114, 2, 'documents', 'record.withdraw.done', 'سُحب المستند', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16115, 2, 'documents', 'record.withdraw.error', 'تعذّر سحب المستند', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16116, 2, 'documents', 'record.withdraw.title', 'سحب {title}؟', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16117, 2, 'documents', 'record.withdrawn.body', 'سحبه {who} في {when}. السجل محفوظ، لكن رموزه لم تعد تؤكّد شيئاً ولا يمكن أن يحدث شيء آخر في مساراته.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16118, 2, 'documents', 'record.withdrawn.bodyNoDate', 'سحبه {who}. السجل محفوظ، لكن رموزه لم تعد تؤكّد شيئاً ولا يمكن أن يحدث شيء آخر في مساراته.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16119, 2, 'documents', 'record.withdrawn.title', 'سُحب هذا المستند', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16120, 2, 'documents', 'routing.act.acknowledge', 'أقِرّ بالاستلام', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16121, 2, 'documents', 'routing.act.approve', 'اعتماد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16122, 2, 'documents', 'routing.act.decision.approved.ends', 'مُعتمَد. اعتُمدت هذه الخطوة، ولا يسمّي المسار جهةً تالية — فلا يمضي المستند أبعد من ذلك في هذا التسلسل.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16123, 2, 'documents', 'routing.act.decision.approved.moved', 'تمت الموافقة. انتقل المستند ووصل إلى {people}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16124, 2, 'documents', 'routing.act.decision.badge', 'قرار', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16125, 2, 'documents', 'routing.act.decision.heading', 'قرارك على هذا المسار', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16126, 2, 'documents', 'routing.act.decision.item', 'الخطوة {position} خطوة قرار، وهي تطلب منك الاعتماد أو الرفض. ووجهة المستند التالية تتبع قرارك لا جهةً تختارها أنت.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16127, 2, 'documents', 'routing.act.decision.pending.approved', 'سُجّل اعتمادك. ولم تُعتمَد هذه الخطوة بعد — فهي لا تزال تنتظر بقية من عُرضت عليهم.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16128, 2, 'documents', 'routing.act.decision.pending.rejected', 'سُجّل رفضك. ولم تُحسَم هذه الخطوة بعد — فوفق قاعدة الاعتماد فيها، لا يزال بإمكان من لم يجيبوا اعتمادها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16129, 2, 'documents', 'routing.act.decision.rejected.ends', 'مرفوض. لم يعد اعتماد هذه الخطوة ممكناً، ولا يرسم المسار طريقاً للرفض — فلا يمضي المستند أبعد من ذلك في هذا التسلسل. والرفض لا ينتقل أبداً إلى حيث كان الاعتماد سيرسله.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16130, 2, 'documents', 'routing.act.decision.rejected.moved', 'تم الرفض. ذهب المستند حيث يرسل المسار حالات الرفض ووصل إلى {people}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16131, 2, 'documents', 'routing.act.delivered', 'أرسل إليك هذا المسار المستند. ولم يُطلب منك التصرّف فيه، فهو ليس بانتظارك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16132, 2, 'documents', 'routing.act.delivered.heading', 'أرسل إليك هذا المسار المستند', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16133, 2, 'documents', 'routing.act.deliveredAtStep', 'أرسلت إليك الخطوة {position} المستند. ولم يُطلب منك التصرّف فيه، فهو ليس بانتظارك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16134, 2, 'documents', 'routing.act.denied.decisionStep', 'الخطوة {position} خطوة قرار: يُجاب عليها بقرار اعتماد أو رفض، ووجهة المستند التالية تتبع ذلك القرار. والإحالة تتيح لك اختيار الوجهة التي وُجدت هذه الخطوة لتقريرها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16135, 2, 'documents', 'routing.act.denied.delivered', 'أرسل إليك هذا المسار المستند ولم يطلب منك شيئاً، فلا يوجد هنا ما تُجيب عليه. ويمكنك مع ذلك إضافة ملاحظة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16136, 2, 'documents', 'routing.act.denied.firstStep', 'وصل هذا العنصر من الخطوة الأولى في المسار، فلا يوجد مستلِم سابق تُعاد إليه. أقِرّ باستلامه، أو أضف ملاحظة تشرح المشكلة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16137, 2, 'documents', 'routing.act.denied.lastStep', 'هذه هي الخطوة الأخيرة في المسار، فلا جهة تُحال إليها. أقِرّ بالاستلام بدلاً من ذلك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16138, 2, 'documents', 'routing.act.denied.noOpenItem', 'ليس لديك عنصر مفتوح على هذا المسار. والعنصر الذي تصرّفت فيه سابقاً لا يمكن التصرّف فيه مرة أخرى — أضف ملاحظة بدلاً من ذلك، فهي تُلحَق بسجل الحركة دون أن تغيّر ما حدث.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16139, 2, 'documents', 'routing.act.error', 'تعذّر تسجيل الإجراء.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16140, 2, 'documents', 'routing.act.error.network', 'تعذّر إرسال الإجراء.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16141, 2, 'documents', 'routing.act.forward', 'إحالة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16142, 2, 'documents', 'routing.act.forwarded.ok', 'تم التسجيل. وصلت الخطوة التالية إلى {people}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16143, 2, 'documents', 'routing.act.heading', 'إجراؤك على هذا المسار', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
