(16145, 2, 'documents', 'routing.act.itemUnknownStep', 'لديك عنصر مفتوح على هذا المسار.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16146, 2, 'documents', 'routing.act.noItem', 'لا شيء على هذا المسار ينتظرك. ولا يزال بإمكانك إضافة ملاحظة — فسجل الحركة لا يقبل التعديل، والتصحيح يُلحَق بجانب ما يصحّحه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16147, 2, 'documents', 'routing.act.note.count', '{used} من {max} حرفاً', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16148, 2, 'documents', 'routing.act.note.decisionLabel', 'السبب (اختياري، يُلحَق بسجل الحركة بجانب قرارك)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16149, 2, 'documents', 'routing.act.note.label', 'ملاحظة (اختيارية، تُلحَق بسجل الحركة)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16150, 2, 'documents', 'routing.act.note.placeholder', 'ماذا ينبغي أن يذكر السجل؟', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
