(16153, 2, 'documents', 'routing.act.noted.ok', 'أُضيفت الملاحظة إلى سجل الحركة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16154, 2, 'documents', 'routing.act.quorum.all', 'يجب أن يعتمدها كل واحد منهم. ورفض واحد يحسمها، لأن الإجماع يصبح مستحيلاً بعده.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16155, 2, 'documents', 'routing.act.quorum.any', 'يكفي اعتماد واحد منهم لإجازتها، فقد يحسمها اعتمادك وحده. والرفض لا يقرّر شيئاً ما دام أحدهم قادراً على الاعتماد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16156, 2, 'documents', 'routing.act.quorum.cohort', 'عُرضت هذه الخطوة على {count} من الأشخاص دفعةً واحدة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16157, 2, 'documents', 'routing.act.quorum.first', 'أول من يجيب منهم يقرّر، بالموافقة أو الرفض. بعد أن يجيب أحدهم لا يُطلب من الآخرين شيء.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16158, 2, 'documents', 'routing.act.quorum.inherited', 'تلك هي قاعدة مساحة العمل هذه لخطوات الاعتماد، وهذه الخطوة لا تتجاوزها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16159, 2, 'documents', 'routing.act.quorum.majority', 'تُعتمَد عندما يعتمدها أكثر من نصفهم، وتُرفض بمجرد أن تصبح الأغلبية المؤيِّدة مستحيلة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16160, 2, 'documents', 'routing.act.quorum.onStep', 'هذه الخطوة تسمّي تلك القاعدة بنفسها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
