(16171, 2, 'documents', 'routing.compose.blocked.incomplete', 'الخطوة {position} لا تزال تحتاج إلى قاعدة وإلى إعدادها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16172, 2, 'documents', 'routing.compose.blocked.noSteps', 'المسار يحتاج إلى خطوة واحدة على الأقل. فالمسار الخالي من الخطوات يُصدر المستند إلى لا أحد ويسجّله على أنه أُرسل.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16173, 2, 'documents', 'routing.compose.cancel', 'إلغاء', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
