(16175, 2, 'documents', 'routing.compose.error.network', 'تعذّر إرسال المسار.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16176, 2, 'documents', 'routing.compose.group.previewError', 'تعذّر تحديد من تصل إليهم هذه المجموعة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16177, 2, 'documents', 'routing.compose.group.previewNetworkError', 'تعذّر تحديد من تصل إليهم هذه المجموعة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16178, 2, 'documents', 'routing.compose.groups.error', 'تعذّر تحميل مجموعات المستخدمين.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16179, 2, 'documents', 'routing.compose.groups.forbidden', 'لا يمكنك سرد مجموعات المستخدمين هنا، فلا تستطيع الخطوة تسمية مجموعة. وسيلزم أن يمنحك المسؤول صلاحية قراءة مجموعات المستخدمين.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16180, 2, 'documents', 'routing.compose.groups.forbiddenNamed', 'لا يمكنك سرد مجموعات المستخدمين هنا، فلا تستطيع الخطوة تسمية مجموعة. وسيلزم أن يمنحك المسؤول صلاحية {slug}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16181, 2, 'documents', 'routing.compose.groups.partial', 'تعذّر تحميل بعض مجموعات المستخدمين، لذا قد تكون هذه القائمة ناقصة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16182, 2, 'documents', 'routing.compose.heading', 'اختر الخطوات التي يسلكها هذا المستند', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16183, 2, 'documents', 'routing.compose.issued', 'تم إنشاء المسار. وصلت الخطوة الأولى إلى {people}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16184, 2, 'documents', 'routing.compose.issuedEmpty', 'أُنشئ المسار، لكن خطوته الأولى لم تشمل أحداً — لا يوجد عضو نشط يحمل ذلك الدور. فلا شيء ينتظر أحداً.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16185, 2, 'documents', 'routing.compose.mode.steps', 'خطوة بخطوة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16186, 2, 'documents', 'routing.compose.mode.template', 'البدء من قالب', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16187, 2, 'documents', 'routing.compose.noRules', 'لا توجد في هذا التثبيت قواعد مسارات مسجّلة، فلا يستطيع المسار تسمية أحد. يوفّر النظام قاعدتين، ويمكن لإضافة أن تضيف المزيد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16188, 2, 'documents', 'routing.compose.people.error', 'تعذّر تحميل الأشخاص.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16189, 2, 'documents', 'routing.compose.people.forbidden', 'لا يمكنك سرد الأشخاص هنا، فلا تستطيع الخطوة تسمية أحد بالاسم. وسيلزم أن يمنحك المسؤول صلاحية قراءة الأشخاص.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16190, 2, 'documents', 'routing.compose.people.forbiddenNamed', 'لا يمكنك سرد الأشخاص هنا، فلا تستطيع الخطوة تسمية أحد بالاسم. وسيلزم أن يمنحك المسؤول صلاحية {slug}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16191, 2, 'documents', 'routing.compose.people.partial', 'تعذّر تحميل بعض الأشخاص، لذا قد تكون هذه القائمة ناقصة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16192, 2, 'documents', 'routing.compose.preview.contract', 'كل خطوة تحدد لمن هي، مثل دور معيّن، لا أشخاصاً بعينهم. ويُحدَّد من هم عند إرسال المستند. وسنخبرك بعدد من وصلت إليهم الخطوة الأولى فور إنشاء المسار.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16193, 2, 'documents', 'routing.compose.roles.error', 'تعذّر تحميل الأدوار.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16194, 2, 'documents', 'routing.compose.roles.forbidden', 'لا يمكنك سرد الأدوار هنا، فلا تستطيع القاعدة تسمية دور. وسيلزم أن يمنحك المسؤول صلاحية قراءة الأدوار.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16195, 2, 'documents', 'routing.compose.roles.forbiddenNamed', 'لا يمكنك سرد الأدوار هنا، فلا تستطيع القاعدة تسمية دور. وسيلزم أن يمنحك المسؤول صلاحية {slug}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16196, 2, 'documents', 'routing.compose.roles.partial', 'تعذّر تحميل بعض الأدوار، لذا قد تكون هذه القائمة ناقصة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16197, 2, 'documents', 'routing.compose.send', 'إرسال المستند', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16198, 2, 'documents', 'routing.compose.sending', 'جارٍ الإرسال…', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16199, 2, 'documents', 'routing.compose.step.delivery', 'يُرسِل دون أن يطلب — كل من تصل إليه هذه الخطوة يُبلَّغ، ويُغلق عنصره فوراً، ويستمر المسار.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16200, 2, 'documents', 'routing.compose.step.down', 'تأخير الخطوة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1);
INSERT INTO "translations" ("id", "language_id", "domain", "key", "translation", "tenant_id", "created_at", "updated_at", "source_managed") VALUES
(16201, 2, 'documents', 'routing.compose.step.fromPlugin', 'من {plugin}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16202, 2, 'documents', 'routing.compose.step.group', 'مجموعة مستخدمين', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16203, 2, 'documents', 'routing.compose.step.groupDynamic', 'المجموعة قاعدة لا قائمة أشخاص محفوظة. ويُحدَّد من تصل إليهم من جديد في كل مرة يتحرّك فيها المستند، فهذا ما تعنيه في الوقت الحالي — لا مجموعة ثُبِّتت على حالها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16204, 2, 'documents', 'routing.compose.step.groupPlaceholder', 'اختر مجموعة مستخدمين', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16205, 2, 'documents', 'routing.compose.step.groupPreviewAll', 'هؤلاء هم الجميع:', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16206, 2, 'documents', 'routing.compose.step.groupPreviewCount', 'تصل إلى {count} من الأشخاص في الوقت الحالي.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16207, 2, 'documents', 'routing.compose.step.groupPreviewEmpty', 'لا تصل هذه المجموعة إلى أحد في الوقت الحالي. والخطوة التي تسمّيها لن تصل إلى أي أحد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16208, 2, 'documents', 'routing.compose.step.groupPreviewLoading', 'جارٍ تحديد من تصل إليهم هذه المجموعة…', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16209, 2, 'documents', 'routing.compose.step.groupPreviewSample', 'تُعرض {shown} من أصل {total} — عيّنة لا المجموعة كاملة:', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16210, 2, 'documents', 'routing.compose.step.groupRetry', 'إعادة المحاولة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16211, 2, 'documents', 'routing.compose.step.groupUnknown', 'تسمّي هذه الخطوة مجموعة المستخدمين رقم {id}، وهي ليست في القائمة التي يمكنك رؤيتها — فقد تكون حُذفت، أو قد لا تستطيع قراءتها. واختيار مجموعة أخرى هنا سيحلّ محلّها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16212, 2, 'documents', 'routing.compose.step.groupUnnamed', 'شخص في مساحة العمل هذه', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16213, 2, 'documents', 'routing.compose.step.label', 'التسمية الظاهرة على الخطوة (اختيارية)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16214, 2, 'documents', 'routing.compose.step.noGroups', 'لم تُعرَّف أي مجموعات مستخدمين هنا بعد. ويستطيع المسؤول تعريف واحدة من صفحة مجموعات المستخدمين، فتتمكّن الخطوة عندئذٍ من تسميتها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16215, 2, 'documents', 'routing.compose.step.noPeople', 'لا يوجد هنا أحد لتسميته.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16216, 2, 'documents', 'routing.compose.step.noRoles', 'لا توجد أدوار متاحة للتسمية.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16217, 2, 'documents', 'routing.compose.step.ordinal', 'الخطوة {position}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16218, 2, 'documents', 'routing.compose.step.people', 'الأشخاص', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16219, 2, 'documents', 'routing.compose.step.peopleHelp', 'تعني هذه الخطوة هؤلاء الأشخاص بالضبط ولا أحد سواهم — ولن تضمّ من ينضمّ لاحقاً. وإذا أردت مجموعة تواكب تغيّر المؤسسة، فسمِّ مجموعة مستخدمين بدلاً من ذلك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16220, 2, 'documents', 'routing.compose.step.peopleMoreMatches', 'تُعرض {shown} من أصل {total} من النتائج — تابع الكتابة لتضييق النطاق.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16221, 2, 'documents', 'routing.compose.step.peopleNoMatches', 'لا أحد يطابق ذلك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16222, 2, 'documents', 'routing.compose.step.peopleNothingSelected', 'لم يُختَر أحد بعد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16223, 2, 'documents', 'routing.compose.step.peopleRemove', 'إزالة {name}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16224, 2, 'documents', 'routing.compose.step.peopleSearch', 'البحث عن الأشخاص بالاسم', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16225, 2, 'documents', 'routing.compose.step.peopleUnknown', 'شخص في مساحة العمل هذه', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16226, 2, 'documents', 'routing.compose.step.pluginConfig', 'تُضبَط هذه القاعدة من الإضافة التي توفّرها. وستُرسَل بلا إعدادات؛ فإن كانت تحتاج إلى إعدادات، فسيبيّن الخادم أيَّها.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16227, 2, 'documents', 'routing.compose.step.remove', 'إزالة الخطوة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
