(16232, 2, 'documents', 'routing.compose.template.approvedGoes', 'الموافقة ← {destination}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16233, 2, 'documents', 'routing.compose.template.blocked.none', 'اختر قالب مسار لتطبيقه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16234, 2, 'documents', 'routing.compose.template.ends', 'تنتهي السلسلة هنا', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
