(16238, 2, 'documents', 'routing.compose.template.loadError', 'تعذّرت قراءة قالب المسار هذا.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16239, 2, 'documents', 'routing.compose.template.loading', 'جارٍ قراءة التصميم…', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16240, 2, 'documents', 'routing.compose.template.none', 'لم يُصمَّم أي قالب مسار هنا بعد. يستطيع من يملك صلاحية تصميم المسارات رسم قالب من صفحة قوالب المسارات، ثم يمكن تطبيقه على أي مستند.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16241, 2, 'documents', 'routing.compose.template.option', '{name} — {count} مراحل', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16242, 2, 'documents', 'routing.compose.template.placeholder', 'اختر قالب مسار', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16243, 2, 'documents', 'routing.compose.template.quorum.all', 'يجب أن يوافق الجميع', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16244, 2, 'documents', 'routing.compose.template.quorum.any', 'تكفي موافقة واحدة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16245, 2, 'documents', 'routing.compose.template.quorum.first', 'أول إجابة تقرّر', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16246, 2, 'documents', 'routing.compose.template.quorum.majority', 'يجب أن يوافق أكثر من النصف', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16247, 2, 'documents', 'routing.compose.template.rejectedGoes', 'الرفض ← {destination}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16248, 2, 'documents', 'routing.compose.template.snapshot', 'يُنسخ التصميم إلى المستند كما هو الآن. وإعادة رسمه لاحقاً لن تُحرّك تعميماً جارياً بالفعل — غير أن كل مرحلة تُسمّي قاعدة، فمن تصل إليه يُحدَّد عندما يبلغها المستند.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16249, 2, 'documents', 'routing.compose.template.stage', 'المرحلة {position}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16250, 2, 'documents', 'routing.compose.templates.error', 'تعذّر تحميل قوالب المسارات.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16251, 2, 'documents', 'routing.compose.templates.forbidden', 'لا يمكنك قراءة قوالب المسارات هنا، فلا يمكن تطبيق تصميم على هذا المستند. وسيلزم أن يمنحك المسؤول صلاحية قراءة قوالب المسارات.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16252, 2, 'documents', 'routing.compose.templates.forbiddenNamed', 'لا يمكنك قراءة قوالب المسارات هنا، فلا يمكن تطبيق تصميم على هذا المستند. وسيلزم أن يمنحك المسؤول صلاحية {slug}.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16253, 2, 'documents', 'routing.compose.templates.partial', 'تعذّر تحميل بعض قوالب المسارات، لذا قد تكون هذه القائمة ناقصة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16254, 2, 'documents', 'routing.compose.title.help', 'إذا تُرك فارغاً، استُخدم عنوان المستند نفسه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16255, 2, 'documents', 'routing.compose.title.helpTemplate', 'إذا تُرك فارغاً، سُمّي المسار باسم القالب الذي يتبعه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16256, 2, 'documents', 'routing.compose.title.label', 'اسم المسار (اختياري)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16257, 2, 'documents', 'routing.description', 'إلى أين أُرسل هذا المستند، وما الذي يمكنك فعله بشأنه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16258, 2, 'documents', 'routing.empty.description', 'لا مسار له، فلم يُطلب من أحد التصرّف فيه ولا شيء في سجل حركته. وإرساله يُنشئ مساراً: مجموعة مرتّبة من الخطوات، تسمّي كل منها قاعدة لا شخصاً.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16259, 2, 'documents', 'routing.empty.title', 'لم يُتداول هذا المستند', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16260, 2, 'documents', 'routing.error.recipients', 'تعذّر تحميل مستلِمي هذا المستند.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16261, 2, 'documents', 'routing.error.routes', 'تعذّر تحميل مسارات هذا المستند.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16262, 2, 'documents', 'routing.error.rules', 'تعذّر تحميل قواعد المسارات.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16263, 2, 'documents', 'routing.fanout.chain.acted', 'تصرّف', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16264, 2, 'documents', 'routing.fanout.chain.more', 'و{count} آخرون على هذا الفرع', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16265, 2, 'documents', 'routing.fanout.chain.open', 'لديه مفتوح', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16266, 2, 'documents', 'routing.fanout.chain.sent', 'أُرسل', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16267, 2, 'documents', 'routing.fanout.chain.unknownStep', 'خطوة غير معروفة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16268, 2, 'documents', 'routing.fanout.chain.withdrawn', 'أُغلق بالسحب', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16269, 2, 'documents', 'routing.fanout.chains.heading', 'الفروع', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16270, 2, 'documents', 'routing.fanout.chains.none', 'لم يصل هذا المسار إلى أحد. فخطوته الأولى شملت مجموعة فارغة من الأشخاص — إذ لم تجد القاعدة أحداً يحمل ذلك الدور.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16271, 2, 'documents', 'routing.fanout.chains.showAll', 'عرض الفروع المتبقّية ({count})', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16272, 2, 'documents', 'routing.fanout.independent', 'تتحرّك هذه الفروع بشكل مستقل — إذ يحدّد كل مستلِم الخطوة التالية نسبةً إلى نفسه، فقد ينتهي فرع بينما لم يُفتح فرع آخر بعد. ولا توجد خطوة واحدة يكون المستند ككل «عندها».', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16273, 2, 'documents', 'routing.fanout.open', '{people} في انتظار التصرّف، عبر {steps} من خطوات هذا المسار.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16274, 2, 'documents', 'routing.fanout.settled', 'لا أحد لديه هذا مفتوحاً. فقد تُصرِّف في كل سلسلة من سلاسل هذا المسار.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16275, 2, 'documents', 'routing.fanout.settledDelivered', 'لا أحد لديه هذا مفتوحًا. تم تسليم كل مسار من مسارات هذا التوجيه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16276, 2, 'documents', 'routing.fanout.settledMixed', 'لا أحد لديه هذا مفتوحًا. كل مسار من مسارات هذا التوجيه مُغلق.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(16277, 2, 'documents', 'routing.fanout.settledWithdrawn', 'لا أحد يتولّى هذا الآن. سُحب المستند، فأُغلق ما كان ينتظر في هذا المسار.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
