(17254, 2, 'onboarding', 'denied.dashboard', 'الانتقال إلى لوحة المعلومات', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17255, 2, 'onboarding', 'denied.description', 'يضبط إعداد التشغيل الأول القيم الافتراضية على مستوى النظام كله، ولذلك لا يمكن تنفيذه إلا من قِبل مشغّل مساحة عمل النظام. سجّل الدخول بحساب المشغّل للمتابعة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17256, 2, 'onboarding', 'denied.title', 'الإعداد مقصور على المشغّل', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17257, 2, 'onboarding', 'error.finalize', 'تعذّر إنهاء إعداد التشغيل الأول', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17258, 2, 'onboarding', 'error.finish', 'تعذّر إنهاء الإعداد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17259, 2, 'onboarding', 'error.load', 'تعذّر تحميل إعدادات النظام', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17260, 2, 'onboarding', 'error.save', 'تعذّر حفظ إعداداتك', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17261, 2, 'onboarding', 'finish.defaults', 'اكتمل الإعداد. يمكنك ضبط كل شيء بدقّة من الإعدادات.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17262, 2, 'onboarding', 'finish.saved', 'اكتمل الإعداد. النظام جاهز.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17263, 2, 'onboarding', 'guide.email.connection.from', 'عنوان المُرسِل واسمه هما ما يراه المستلِمون بوصفه مصدر الرسالة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17264, 2, 'onboarding', 'guide.email.connection.heading', 'اتصال SMTP', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17265, 2, 'onboarding', 'guide.email.connection.host', 'المضيف — خادم SMTP لدى مزوّدك، مثل mail.yourdomain.com (لوحة cPanel)، أو smtp.gmail.com (جوجل)، أو email-smtp.<region>.amazonaws.com (خدمة Amazon SES).', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17266, 2, 'onboarding', 'guide.email.connection.port', 'المنفذ والتشفير متلازمان: 587 ← TLS ‏(STARTTLS) أو 465 ← SSL. استخدم اسم مضيف تغطّيه شهادة TLS فعلياً.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17267, 2, 'onboarding', 'guide.email.connection.username', 'اسم المستخدم هو عادةً عنوان البريد الإلكتروني الكامل للصندوق الذي ترسل منه.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17268, 2, 'onboarding', 'guide.email.credentials.cpanel', 'لوحة cPanel: من Email Accounts ← Connect Devices تظهر لك بيانات المضيف والمنافذ واسم المستخدم.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17269, 2, 'onboarding', 'guide.email.credentials.google', 'Google Workspace / Gmail: أنشئ كلمة مرور للتطبيقات (مع تفعيل التحقّق بخطوتين) واستخدمها ككلمة مرور SMTP.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17270, 2, 'onboarding', 'guide.email.credentials.heading', 'أين تجد بيانات اعتمادك', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17271, 2, 'onboarding', 'guide.email.credentials.ses', 'خدمة Amazon SES: أنشئ بيانات اعتماد SMTP من وحدة تحكّم SES (وهي مختلفة عن مفاتيح AWS الخاصة بك).', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17272, 2, 'onboarding', 'guide.email.link', 'فتح إعدادات البريد (كلمة المرور وإرسال رسالة اختبار)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17273, 2, 'onboarding', 'guide.email.password.body', 'تُحفظ كلمة مرور SMTP مشفَّرة وتُضبَط من صفحة إعدادات البريد، وفيها أيضاً زر «إرسال رسالة اختبار» للتحقّق من الاتصال من طرف إلى طرف.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17274, 2, 'onboarding', 'guide.email.password.heading', 'كلمة المرور ورسالة الاختبار', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17275, 2, 'onboarding', 'guide.email.summary', 'كيفية ربط صندوق بريد عبر SMTP — وأين تجد التفاصيل.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17276, 2, 'onboarding', 'guide.email.transport.heading', 'وسيلة النقل', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17277, 2, 'onboarding', 'guide.email.transport.options', '«بدون» تعطّل البريد كلياً. و«السجل» تكتب الرسائل في سجل التطبيق (مفيدة أثناء الاختبار). و«SMTP» ترسل بريداً حقيقياً عبر مزوّد البريد لديك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17278, 2, 'onboarding', 'guide.hide', 'إخفاء', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17279, 2, 'onboarding', 'guide.show', 'إظهار', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17280, 2, 'onboarding', 'guide.signin.link', 'فتح إعدادات الدخول الموحّد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17281, 2, 'onboarding', 'guide.signin.masterSwitch', 'هذا هو المفتاح الرئيسي للدخول الموحّد على مستوى النظام كله. وعند إيقافه، يُعطَّل كل مزوّد هوية مضبوط.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17282, 2, 'onboarding', 'guide.signin.providers', 'تُضاف المزوّدات المفردة (مثل جوجل) من صفحة إعدادات الدخول الموحّد: أنشئ عميل OAuth لدى مزوّدك، واضبط عنوان إعادة التوجيه الذي يعطيك إياه، ثم الصق معرّف العميل وسرّه هناك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17283, 2, 'onboarding', 'guide.signin.summary', 'المفتاح الرئيسي للدخول الموحّد؛ وتُضاف المزوّدات المفردة من صفحة الدخول الموحّد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17284, 2, 'onboarding', 'guide.signup.approval', 'خيار «اشتراط موافقة المسؤول» يُبقي كل حساب جديد «قيد الانتظار» حتى يوافق عليه أحد المسؤولين. أبقِه مفعّلاً عندما يكون التسجيل مفتوحاً حتى لا يحصل أحد على صلاحية دون مراجعة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17285, 2, 'onboarding', 'guide.signup.publicSignup', 'يتيح التسجيل العام لأي شخص إنشاء حساب من شاشة تسجيل الدخول. وهو معطّل افتراضياً — فالنظام الذي يزوّده المشغّل يفتحه عن قصد.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17286, 2, 'onboarding', 'guide.signup.summary', 'ما الذي يعنيه التسجيل المفتوح والموافقة بالنسبة لنظامك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17287, 2, 'onboarding', 'guide.storage.driver.heading', 'المشغّل', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17288, 2, 'onboarding', 'guide.storage.driver.local', 'الخيار «local» يخزّن الملفات المرفوعة على قرص الخادم — وهو مناسب لتثبيت على عقدة واحدة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17289, 2, 'onboarding', 'guide.storage.driver.s3', 'لأجل المتانة أو التشغيل على عدة عقد، استخدم مخزن كائنات متوافقاً مع S3 ‏(AWS S3، أو MinIO، أو Cloudflare R2، أو Backblaze B2، …) بضبط المشغّل على «s3».', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17290, 2, 'onboarding', 'guide.storage.s3.accessKey', 'مفتاح الوصول — معرّف المفتاح العام. أما المفتاح السرّي المقابل فيُزوَّد عبر بيئة النشر ولا يُحفظ هنا أبداً.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17291, 2, 'onboarding', 'guide.storage.s3.endpoint', 'نقطة النهاية — العنوان الأساسي لمخزن الكائنات (مثل https://s3.amazonaws.com، أو نقطة نهاية MinIO/R2 لديك).', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17292, 2, 'onboarding', 'guide.storage.s3.heading', 'إعدادات S3', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17293, 2, 'onboarding', 'guide.storage.s3.pathStyle', 'العنونة بنمط المسار — فعّلها مع معظم البوابات المستضافة ذاتياً (مثل MinIO)؛ أما AWS فتستخدم نمط الاستضافة الافتراضية.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17294, 2, 'onboarding', 'guide.storage.s3.publicBaseUrl', 'العنوان الأساسي العام — اضبطه فقط إذا كانت الأصول تُقدَّم من مضيف مختلف (شبكة توصيل محتوى) عن نقطة النهاية.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17295, 2, 'onboarding', 'guide.storage.s3.region', 'المنطقة / الحاوية — كما أنشأتهما في وحدة تحكّم مزوّدك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17296, 2, 'onboarding', 'guide.storage.summary', 'احتفظ بالملفات على القرص المحلي، أو وجّهها إلى مخزن كائنات متوافق مع S3.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17297, 2, 'onboarding', 'guide.toggle', 'بحاجة إلى مساعدة؟', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17298, 2, 'onboarding', 'nav.back', 'رجوع', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17299, 2, 'onboarding', 'nav.continue', 'متابعة', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17300, 2, 'onboarding', 'nav.finish', 'إنهاء الإعداد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17301, 2, 'onboarding', 'nav.finish.pending', 'جارٍ الحفظ…', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17302, 2, 'onboarding', 'nav.start', 'لنبدأ', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17303, 2, 'onboarding', 'review.empty', 'أبقيتَ على القيم الافتراضية الموصى بها في كل شيء. أنهِ الإعداد لإتمامه — ويمكنك تعديل أي إعداد لاحقاً من الإعدادات العامة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17304, 2, 'onboarding', 'review.value.off', 'معطّل', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17305, 2, 'onboarding', 'review.value.on', 'مفعّل', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17306, 2, 'onboarding', 'step.email.description', 'اربط صندوق بريد ليتمكّن النظام من إرسال رسائل التحقّق والدعوات والإشعارات.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17307, 2, 'onboarding', 'step.email.title', 'البريد الإلكتروني (SMTP)', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17308, 2, 'onboarding', 'step.general.description', 'كيف يعرّف نظامك بنفسه لدى كل مساحة عمل.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17309, 2, 'onboarding', 'step.general.title', 'أساسيات النظام', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17310, 2, 'onboarding', 'step.review.description', 'راجع التغييرات أدناه ثم أنهِ الإعداد. ويبقى كل شيء قابلاً للتعديل من الإعدادات العامة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17311, 2, 'onboarding', 'step.review.title', 'المراجعة والإنهاء', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17312, 2, 'onboarding', 'step.signin.description', 'الدخول الموحّد على مستوى النظام كله.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17313, 2, 'onboarding', 'step.signin.title', 'تسجيل الدخول والدخول الموحّد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17314, 2, 'onboarding', 'step.signup.description', 'قرّر ما إذا كان بإمكان الأشخاص تسجيل أنفسهم، وما إذا كانت الحسابات الجديدة تحتاج إلى موافقة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17315, 2, 'onboarding', 'step.signup.title', 'ضوابط التسجيل', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17316, 2, 'onboarding', 'step.storage.description', 'أين تُحفظ الملفات المرفوعة (المستندات والهوية البصرية وملفات التصدير).', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17317, 2, 'onboarding', 'step.storage.title', 'تخزين الملفات', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17318, 2, 'onboarding', 'step.welcome.description', 'أهلاً بك — يضبط هذا المعالج القصير القيم الافتراضية على مستوى النظام كله لتثبيتك.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17319, 2, 'onboarding', 'step.welcome.title', 'أهلاً بك', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17320, 2, 'onboarding', 'stepper.label', 'تقدّم الإعداد', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17321, 2, 'onboarding', 'subtitle', 'بضع قيم افتراضية للبدء. ويمكنك تغيير أيٍّ منها لاحقاً من الإعدادات العامة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17322, 2, 'onboarding', 'title', 'إعداد نظامك', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17323, 2, 'onboarding', 'welcome.connect', 'سنربط أيضاً <0>البريد الإلكتروني (SMTP)</0> و<1>تخزين الملفات</1> — لكل خطوة دليل قصير يرشدك إلى ما تحتاجه. لا شيء من ذلك نهائي: كل إعداد يبقى قابلاً للتعديل لاحقاً من <2>الإعدادات العامة</2>.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17324, 2, 'onboarding', 'welcome.intro', 'هذا نظام جديد. وتضبط الخطوات القليلة التالية القيم الافتراضية التي ترثها كل مساحة عمل — اسم النظام وجهة اتصال الدعم، وما إذا كان بإمكان الأشخاص تسجيل أنفسهم، وكيفية عمل تسجيل الدخول.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17325, 2, 'plugin', 'access.grace', 'انتهى الوصول إلى هذه الإضافة. تبقى تعمل حتى {date}، ثم تصبح للقراءة فقط. يمكن لمن يدير الفوترة شراؤها من الإعدادات › الإضافات.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17326, 2, 'plugin', 'access.licenceGrace', 'ترخيص منصتك لهذه الإضافة يحتاج إلى تجديد قريباً.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17327, 2, 'plugin', 'access.readOnly', 'للقراءة فقط: يمكنك رؤية كل شيء هنا دون تغييره. لم يُحذف شيء. يمكن لمن يدير الفوترة شراؤها مجدداً من الإعدادات › الإضافات.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17328, 2, 'plugin', 'access.unlicensed', 'للقراءة فقط: انتهى ترخيص منصتك لهذه الإضافة. تواصل مع مشغّل المنصة.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17329, 2, 'plugin', 'action.empty', 'هذا الإجراء لا يستقبل أي مدخلات.', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17330, 2, 'plugin', 'action.error.http', 'فشل الطلب (HTTP {status})', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17331, 2, 'plugin', 'action.field.required', '{label} مطلوب', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
(17332, 2, 'plugin', 'action.issues.item', 'العنصر {index}', NULL, '1970-01-02 03:04:05', '1970-01-02 03:04:05', 1),
